// Plan-based feature gating: mirrors the server's requiredPlanForPath so that page navigation
// matches what each plan card actually lists. The server is the source of truth / enforcement;
// this only controls what the UI shows and prevents a locked page from being opened.
const PLAN_ORDER={free:0,business:1,pro:2};
const PAGE_PLAN_REQUIREMENT={
  analytics:'business', reports:'business', branches:'business', staff:'business',
  purchases:'business', procurement:'business', accounting:'business', budgetControl:'business',
  financialCenter:'business', cashflow:'business', planner:'business', customerIntel:'business',
  marketing:'business', loyalty:'business', documents:'business', receivables:'business',
  predictive:'pro', decisionAutomation:'pro', smartActions:'pro', automationCenter:'pro',
  commandCenter:'pro', systemHealth:'pro', dataAudit:'pro'
};
function userPlanRank(){return PLAN_ORDER[user?.plan||'free']??0;}
function planRequirementFor(pageId){return PAGE_PLAN_REQUIREMENT[pageId]||null;}
function planAllowsPage(pageId){const req=planRequirementFor(pageId);if(!req)return true;return userPlanRank()>=PLAN_ORDER[req];}

// ---------- App platform detection (Payment Hub: web-only) ----------
// The BIGJOE Android/iOS apps are Capacitor wrappers around this same web app. Capacitor
// injects a global `Capacitor` object into the page at runtime, so `Capacitor.getPlatform()`
// tells us whether we're running inside the native shell ('ios'/'android') or a plain
// browser/PWA ('web'). Payment Hub (receiving-payment account setup) is only ever shown on
// 'web' — the consolidated BIGJOE website — matching the server-side restriction.
function bigjoePlatform(){
  try{
    if(window.Capacitor?.isNativePlatform?.() && window.Capacitor.getPlatform){
      const p=window.Capacitor.getPlatform();
      if(p==='ios'||p==='android')return p;
    }
  }catch{}
  return 'web';
}
window.__bigjoePlatform=bigjoePlatform();
function isNativeApp(){return window.__bigjoePlatform!=='web';}
const PAYMENT_HUB_PAGE_ID='paymentHub';

const $=id=>document.getElementById(id);
function toast(m,error=false){$("toast").textContent=m;$("toast").className=error?"show error":"show";setTimeout(()=>$("toast").className="",3000)}
async function api(path,options={}){const fetchOptions={headers:{"Content-Type":"application/json","X-BigJoe-Platform":window.__bigjoePlatform||'web',...(options.headers||{})},...options};if(!fetchOptions.method||String(fetchOptions.method).toUpperCase()==="GET"){fetchOptions.cache="no-store";}const timeoutMs=Number(options.timeout||15000);if(!fetchOptions.signal){const controller=new AbortController();fetchOptions.signal=controller.signal;fetchOptions.__bigjoeTimer=setTimeout(()=>controller.abort(),timeoutMs);}let r;try{r=await fetch(path,fetchOptions)}catch(e){if(e.name==='AbortError')throw new Error(`Request timed out while loading ${path}. Please try again.`);throw e}finally{if(fetchOptions.__bigjoeTimer)clearTimeout(fetchOptions.__bigjoeTimer)}let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||"Request failed");return d}

async function loadNetworkAccess(){try{const d=await api('/api/network-info');const urls=d.lan_urls||[];const el=document.getElementById('lanAccessUrl'),st=document.getElementById('lanAccessStatus');if(!el||!st)return;if(urls.length){el.textContent=urls[0];st.textContent='Same-Wi-Fi phone access is ready';window.__lanUrl=urls[0]}else{el.textContent=window.location.origin;st.textContent='Use this address on your phone when BIGJOE is publicly hosted';window.__lanUrl=window.location.origin}}catch(e){const el=document.getElementById('lanAccessUrl');if(el)el.textContent=window.location.origin;window.__lanUrl=window.location.origin}}
function copyLanUrl(){const u=window.__lanUrl||document.getElementById('lanAccessUrl')?.textContent||window.location.origin;navigator.clipboard?.writeText(u).then(()=>toast('BIGJOE address copied.')).catch(()=>toast(u));}
