(function initWelcomeFeatureSlider(){
  const slides=[...document.querySelectorAll('.welcome-ad-slide')],dots=[...document.querySelectorAll('.welcome-ad-dots span')];
  if(!slides.length)return;
  let i=0;
  const show=(n)=>{i=(n+slides.length)%slides.length;slides.forEach((el,k)=>el.classList.toggle('active',k===i));dots.forEach((el,k)=>el.classList.toggle('active',k===i));};
  setInterval(()=>show(i+1),4200);
})();
function setScreen(screen){
  document.body.classList.remove("screen-welcome","screen-auth","screen-app","public-site-hidden");
  document.body.classList.add(`screen-${screen}`);
  if(screen!=="welcome") document.body.classList.add("public-site-hidden");
  if(window.location.hash) history.replaceState(null,"",window.location.pathname+window.location.search);
  window.scrollTo({top:0,left:0,behavior:"auto"});
}
function setPublicSiteVisible(visible){
  document.querySelectorAll("#landing,.public-extra").forEach(el=>el.classList.toggle("hidden",!visible));
}
function showWelcome(){
  setPublicSiteVisible(true);
  $("landing").classList.remove("hidden");
  $("auth").classList.add("hidden");
  $("app").classList.add("hidden");
  const nav=$("nav");
  if(nav) nav.innerHTML=`<button class="top-start-free" onclick="showAuth('login')">Start free</button>`;
  setScreen("welcome");
}
function togglePasswordVisibility(){const input=$("password"),btn=document.querySelector(".password-toggle");if(!input||!btn)return;const show=input.type==="password";input.type=show?"text":"password";btn.textContent=show?"Hide":"Show";btn.setAttribute("aria-label",show?"Hide password":"Show password");btn.setAttribute("aria-pressed",String(show));}
function showAuth(mode){
  setPublicSiteVisible(false);
  $("landing").classList.add("hidden");
  $("app").classList.add("hidden");
  $("auth").classList.remove("hidden");
  const reg=mode==="register";
  $("authTitle").textContent=reg?"Create your account":"Welcome back";
  $("authButton").textContent=reg?"Create account":"Log in";
  $("nameField").style.display=reg?"block":"none";
  $("authSwitch").innerHTML=reg?`Already have an account? <a href="#" onclick="showAuth('login')">Log in</a>`:`New to BIGJOE? <a href="#" onclick="showAuth('register')">Create an account</a>`;
  $("authForm").dataset.mode=mode;
  const nav=$("nav");
  if(nav) nav.innerHTML='';
  setScreen("auth");
  setTimeout(()=>$("email")?.focus(),50);
}
$("authForm").onsubmit=async e=>{e.preventDefault();const form=e.currentTarget;const btn=$("authButton");const original=btn.textContent;btn.disabled=true;btn.textContent="Please wait...";try{const mode=form.dataset.mode||"login",email=$("email").value.trim(),password=$("password").value,name=$("name").value.trim();if(!email||!password||(mode==="register"&&!name)){throw new Error("Please enter all required fields.")}const d=await api("/api/"+(mode==="register"?"register":"login"),{method:"POST",body:JSON.stringify({name,email,password})});if(!d||!d.user) throw new Error("Login completed but no account session was returned. Please try again.");user=d.user;await renderApp()}catch(e){console.error("BIGJOE authentication error:",e);toast(e.message||"Unable to log in. Please try again.",true)}finally{btn.disabled=false;btn.textContent=original}}
async function renderApp(){
  setPublicSiteVisible(false);
  $("landing").classList.add("hidden");
  $("auth").classList.add("hidden");
  $("app").classList.remove("hidden");
  $("nav").innerHTML='';
  setScreen("app");
  try{const a=await api("/api/actor");actor=a.actor||actor}catch{}
  $("userName").textContent=actor.type==='staff'?actor.name:user.name;
  $("userPlan").textContent=actor.type==='staff'?`Staff • ${title(actor.role)}`:title(user.plan);
  applyStaffUI();
  applyPlanUI();
  applyPlatformUI();
  if(actor.type==='owner'){await loadBranches();await loadAll();showPage('overview');ensurePageRefreshButtons();}
  else {
    if(staffHas('branches')) await loadBranches();
    if(staffHas('inventory')) await loadInventory();
    if(staffHas('customers')) await loadCustomers();
    if(staffHas('sales')) await loadSales();
    if(staffHas('expenses')) await loadExpenses();
    if(staffHas('dashboard')) await loadDashboard();
    showPage('overview');
  }
  window.scrollTo({top:0,left:0,behavior:'auto'});
}
function title(s){return s.charAt(0).toUpperCase()+s.slice(1)}

function setManagementReportPreset(type){
  const now=new Date();
  let start=new Date(now.getFullYear(),now.getMonth(),1);
  if(type==='year') start=new Date(now.getFullYear(),0,1);
  if($('managementReportStart')) $('managementReportStart').value=start.toISOString().slice(0,10);
  if($('managementReportEnd')) $('managementReportEnd').value=now.toISOString().slice(0,10);
  if(!$('reports')?.classList.contains('hidden')) loadManagementReports();
}
function setManagementReportPresetSilent(){
  const now=new Date(); const start=new Date(now.getFullYear(),now.getMonth(),1);
  if($('managementReportStart') && !$('managementReportStart').value) $('managementReportStart').value=start.toISOString().slice(0,10);
  if($('managementReportEnd') && !$('managementReportEnd').value) $('managementReportEnd').value=now.toISOString().slice(0,10);
}
function reportTable(rows,headers){
  if(!rows.length) return '<div class="empty">No data available for the selected period.</div>';
  return `<div class="table-wrap report-table-wrap"><table class="report-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
}
function reportOwnerName(){const name=String(user?.name||'').trim();return name||'Business Owner'}
function businessName(){return String(user?.business_profile?.business_name||user?.business_name||'').trim()||'BIGJOE'}
function brandingProfile(){return user?.business_profile||{}}
function reportBrandHeader(){const p=brandingProfile();const logo=p.show_logo!==false&&p.logo_data_url?`<img class="report-brand-logo" src="${p.logo_data_url}" alt="Business logo">`:'';const owner=p.show_owner_name!==false?`<div class="report-brand-owner">Prepared for <b>${esc(reportOwnerName())}</b></div>`:'';const contact=p.show_contact_info!==false?[p.phone,p.email,p.address].filter(Boolean).map(esc).join(' • '):'';const contactHtml=contact?`<div class="report-brand-contact">${contact}</div>`:'';const powered=p.show_branding!==false?`<div class="report-brand-powered">Powered by BIGJOE Business AI</div>`:'';return `<div class="report-brand-header">${logo}<div class="report-brand-copy"><div class="report-brand-business">${esc(businessName())}</div>${owner}${contactHtml}${powered}</div></div>`}
function reportPersonalTitle(){const name=reportOwnerName();return name==='Business Owner'?'Your Business Report':`${esc(name)}'s Business Report`}
function reportPersonalSalesTitle(){const name=reportOwnerName();return name==='Business Owner'?'Your Sales Report':`${esc(name)}'s Sales Report`}
function reportSummaryMetric(label,value,cls=''){return `<div class="report-metric ${cls}"><span>${esc(label)}</span><b>${value}</b></div>`}
async function loadManagementReports(){
  try{
    setManagementReportPresetSilent();
    const start=$('managementReportStart')?.value||''; const end=$('managementReportEnd')?.value||'';
    let d=null;
    try{ d=await api(`/api/dashboard?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}&branch_id=all`); }
    catch(err){
      console.warn('Management dashboard report fallback:',err);
      d={summary:{revenue:0,profit:0,cost:0,expenses:0,net_profit:0,gross_margin:0,expense_ratio:0,inventory_value:0},best_products:[],expense_categories:[],top_customers:[],stock_risk:[],margin_opportunities:[],range:{start,end}};
    }
    const consolidated=await api(`/api/branches/consolidated?from=${encodeURIComponent(start)}&to=${encodeURIComponent(end)}`).catch(()=>({branches:[],totals:{}}));
    if($('reportBranchSummary')) $('reportBranchSummary').innerHTML=(consolidated.branches||[]).map(b=>`<div class="insight"><b>${esc(b.branch_name)}</b><span>Revenue ${money(b.revenue)} · Gross profit ${money(b.gross_profit)} · Expenses ${money(b.expenses)} · Net ${money(b.net_profit)}</span></div>`).join('')||'<div class="empty">No branch activity in this period.</div>';
    window.__managementReportData=d;
    const s=d.summary||{}; const loss=Number(s.net_profit||0)<0; const status=loss?'Needs immediate attention':'Operating positively';
    const headline=loss?`Revenue of ${money(s.revenue)} produced a net loss of ${money(Math.abs(s.net_profit))}.`:`Revenue of ${money(s.revenue)} produced net profit of ${money(s.net_profit)}.`;
    const topExpense=(d.expense_categories||[])[0], topProduct=(d.best_products||[])[0];
    if($('reportExecutive')) $('reportExecutive').innerHTML=`${reportBrandHeader()}<div class="settings-note"><b>Report scope:</b> All active branches</div><div class="section-head"><div><h3>🧠 ${reportPersonalTitle()}</h3><p class="muted">Your business performance for ${esc(start)} to ${esc(end)} • Powered by BIGJOE Business AI</p></div><span class="badge ${loss?'danger-badge':'success-badge'}">${status}</span></div><div class="report-metrics">${reportSummaryMetric('Revenue',money(s.revenue))}${reportSummaryMetric('Gross Profit',money(s.profit))}${reportSummaryMetric('Operating Expenses',money(s.expenses),'danger')}${reportSummaryMetric('Net Profit / Loss',money(s.net_profit),loss?'danger':'')}</div><p class="report-narrative"><b>Management interpretation:</b> ${headline} Gross margin is ${Number(s.gross_margin||0).toFixed(1)}% and operating expenses are ${Number(s.expense_ratio||0).toFixed(1)}% of revenue. ${topExpense?`The largest recorded expense category is ${esc(topExpense.category)} at ${money(topExpense.total)} (${Number(topExpense.share||0).toFixed(1)}% of expenses).`:''} ${topProduct?`The leading product by units sold is ${esc(topProduct.name)} with ${Number(topProduct.quantity||0).toLocaleString()} unit(s) sold.`:''}</p>`;
    if($('reportsPageTitle')) $('reportsPageTitle').textContent='📑 '+reportPersonalTitle();
    if($('reportSalesTitle')) $('reportSalesTitle').textContent='📈 '+reportPersonalSalesTitle();
    if($('reportProfitLoss')) $('reportProfitLoss').innerHTML=reportTable([`<tr><td>Revenue</td><td>${money(s.revenue)}</td></tr>`,`<tr><td>Cost of goods sold</td><td>${money(s.cost)}</td></tr>`,`<tr><td>Gross profit</td><td>${money(s.profit)}</td></tr>`,`<tr><td>Operating expenses</td><td>${money(s.expenses)}</td></tr>`,`<tr class="total-row"><td><b>Net profit / loss</b></td><td><b>${money(s.net_profit)}</b></td></tr>`],['Item','Amount']);
    const salesRows=(d.best_products||[]).map(x=>`<tr><td>${esc(x.name)}</td><td>${Number(x.quantity||0).toLocaleString()}</td><td>${money(x.revenue)}</td><td>${money(x.profit)}</td><td>${Number(x.margin||0).toFixed(1)}%</td></tr>`); if($('reportSalesPerformance')) $('reportSalesPerformance').innerHTML=reportTable(salesRows,['Product','Units','Revenue','Profit','Margin']);
    const expenseRows=(d.expense_categories||[]).map(x=>`<tr><td>${esc(x.category)}</td><td>${money(x.total)}</td><td>${Number(x.share||0).toFixed(1)}%</td></tr>`); if($('reportExpenses')) $('reportExpenses').innerHTML=reportTable(expenseRows,['Category','Amount','Share']);
    const reportProducts=products||[]; const invRows=reportProducts.map(x=>{const qty=Number(x.branch_quantity??x.stock_quantity??0),val=qty*Number(x.cost_price||0),potential=(Number(x.selling_price||0)-Number(x.cost_price||0))*qty;return `<tr><td>${esc(x.name)}</td><td>${qty.toLocaleString()} ${esc(x.unit||'')}</td><td>${money(x.cost_price)}</td><td>${money(val)}</td><td>${money(potential)}</td></tr>`}); if($('reportInventory')) $('reportInventory').innerHTML=reportTable(invRows,['Product','Stock','Cost/unit','Stock value','Potential profit'])+`<div class="report-total"><b>Total inventory value:</b> ${money(s.inventory_value)}</div>`;
    const customerRows=(d.top_customers||[]).map(x=>`<tr><td>${esc(x.name)}</td><td>${Number(x.purchases||0)}</td><td>${money(x.total)}</td></tr>`); if($('reportCustomers')) $('reportCustomers').innerHTML=reportTable(customerRows,['Customer','Purchases','Total spent']);
    const priorities=[]; if(loss) priorities.push('Reduce avoidable operating costs and increase profitable sales before adding new expenses.'); if(topExpense&&Number(topExpense.share)>=50) priorities.push(`Review ${topExpense.category}, which represents ${Number(topExpense.share).toFixed(1)}% of operating expenses.`); (d.stock_risk||[]).filter(x=>x.risk!=='healthy').slice(0,2).forEach(x=>priorities.push(`${x.risk_label}: monitor ${x.name} and plan replenishment.`)); (d.margin_opportunities||[]).slice(0,2).forEach(x=>priorities.push(`Review ${x.name}'s ${Number(x.margin||0).toFixed(1)}% margin.`)); if(!priorities.length) priorities.push('Continue monitoring sales, margins, expenses and stock. No urgent management priority was detected.'); if($('reportPriorities')) $('reportPriorities').innerHTML=priorities.map((x,i)=>`<div class="action-item"><span>${i+1}</span><div>${esc(x)}</div></div>`).join('');
  }catch(e){console.error('Management report error',e);toast(e.message||'Unable to load Business Report.',true)}
}

