function staffHas(permission){return actor.type==='owner'||(Array.isArray(actor.permissions)&& (actor.permissions.includes('*')||actor.permissions.includes(permission)));}
function applyStaffUI(){
  if(actor.type==='owner')return;
  const map={overview:loadOverviewPage,dashboard:'dashboard',branches:'branches',sales:'sales',inventory:'inventory',customers:'customers',reports:'reports',analytics:'reports',financialCenter:'financial',accounting:'expenses',planner:'ai',cashflow:'financial',budgetControl:'expenses',customerIntel:'customers',marketing:'ai',loyalty:'customers',documents:'sales',receivables:'customers',purchases:'inventory',procurement:'inventory',predictive:'reports',decisionAutomation:'reports',smartActions:'reports',products:'inventory',categories:'inventory',suppliers:'inventory',expenses:'expenses',tools:'ai',plansPage:null,settings:null,staff:'staff',systemHealth:'staff'};
  document.querySelectorAll('.overview-main-nav').forEach(btn=>{const m=btn.getAttribute('onclick')||'';const hit=m.match(/showPage\('([^']+)'/);if(hit){const perm=map[hit[1]];if(perm&& !staffHas(perm))btn.style.display='none';}});
  document.querySelectorAll('.features-dropdown button').forEach(btn=>{const m=btn.getAttribute('onclick')||'';const hit=m.match(/showPage\('([^']+)'/);if(hit){const perm=map[hit[1]];btn.style.display=(perm&& !staffHas(perm))?'none':'block';if(hit[1]==='settings'||hit[1]==='staff')btn.style.display='none';}});
}
// Marks nav buttons that link to a page above the business's current plan with a small lock
// badge (rather than hiding them) so people can see what upgrading unlocks. Re-run whenever
// the app renders or the plan changes.
function applyPlanUI(){
  const buttons=[...document.querySelectorAll('.overview-main-nav'),...document.querySelectorAll('.features-dropdown button')];
  buttons.forEach(btn=>{
    const m=btn.getAttribute('onclick')||'';const hit=m.match(/showPage\('([^']+)'/);if(!hit)return;
    const pageId=hit[1],req=planRequirementFor(pageId);
    const existing=btn.querySelector('.plan-lock-badge');
    if(req && !planAllowsPage(pageId)){
      btn.classList.add('plan-locked');
      if(!existing){const b=document.createElement('span');b.className='plan-lock-badge';b.textContent=`🔒 ${title(req)}`;btn.appendChild(b);}
    } else {
      btn.classList.remove('plan-locked');
      if(existing)existing.remove();
    }
  });
}
// Hides every entry point into Payment Hub (nav/menu buttons, the "Configure Flutterwave"
// shortcut on the Plans page, the onboarding checklist link) when running inside the
// Android/iOS apps. showPage() also blocks direct navigation as a second layer, and the
// server rejects the underlying API calls regardless of what the client shows — this
// function is purely cosmetic (removing an entry point the user could never actually use).
function applyPlatformUI(){
  if(!isNativeApp())return;
  document.querySelectorAll('[onclick]').forEach(el=>{
    const m=el.getAttribute('onclick')||'';
    if(m.includes(`showPage('${PAYMENT_HUB_PAGE_ID}'`)) el.style.display='none';
  });
}

// ---------- Installable desktop/PC app (PWA install) ----------
// BIGJOE already ships a manifest.json + service worker, which is what makes Chrome/Edge
// on Windows, Mac and Linux offer a one-click "Install BIGJOE" that adds a real desktop app
// (own window, taskbar/dock icon, Start Menu entry) — no separate download needed. This
// just surfaces that install prompt as a visible button instead of relying on people
// noticing the small icon in the address bar. Requires the site to be served over HTTPS.
let deferredInstallPrompt=null;
function isStandaloneDisplay(){
  try{ return window.matchMedia?.('(display-mode: standalone)')?.matches || window.navigator.standalone===true; }catch{return false;}
}
function ensureInstallButton(){
  if(isStandaloneDisplay() || isNativeApp()) return;
  if(document.getElementById('bigjoeInstallBtn')) return;
  const btn=document.createElement('button');
  btn.id='bigjoeInstallBtn'; btn.type='button'; btn.className='bigjoe-install-fab'; btn.style.display='none';
  btn.innerHTML='⬇ Install BIGJOE';
  btn.onclick=triggerInstall;
  document.body.appendChild(btn);
}
async function triggerInstall(){
  const btn=document.getElementById('bigjoeInstallBtn');
  if(!deferredInstallPrompt){
    toast('Look for the install icon in your browser\'s address bar, or use the browser menu → "Install BIGJOE" / "Add to Home Screen".');
    return;
  }
  if(btn)btn.disabled=true;
  deferredInstallPrompt.prompt();
  const choice=await deferredInstallPrompt.userChoice;
  deferredInstallPrompt=null;
  if(btn){btn.style.display='none';btn.disabled=false;}
  toast(choice.outcome==='accepted'?'BIGJOE is installing…':'Install dismissed — you can install anytime from the browser menu.');
}
window.addEventListener('beforeinstallprompt',(e)=>{
  e.preventDefault();
  deferredInstallPrompt=e;
  ensureInstallButton();
  const btn=document.getElementById('bigjoeInstallBtn');
  if(btn)btn.style.display='inline-flex';
});
window.addEventListener('appinstalled',()=>{
  deferredInstallPrompt=null;
  document.getElementById('bigjoeInstallBtn')?.remove();
  toast('🎉 BIGJOE installed. You can launch it like any other app from now on.');
});
ensureInstallButton();

function toggleFeaturesMenu(e){e.stopPropagation();const m=$("featuresDropdown");const trigger=e.currentTarget||e.target.closest?.(".menu-trigger");if(m){const open=!m.classList.contains("open");m.classList.toggle("open",open);trigger?.setAttribute("aria-expanded",String(open));}}
