function showClickFeedback(btn){if(!btn||btn.disabled)return;btn.classList.remove("click-confirmed");void btn.offsetWidth;btn.classList.add("click-confirmed");const old=btn.querySelector(".click-sign");if(old)old.remove();const sign=document.createElement("span");sign.className="click-sign";sign.textContent="✓";btn.appendChild(sign);setTimeout(()=>{sign.remove();btn.classList.remove("click-confirmed")},900);}
document.addEventListener("click",e=>{const m=$("featuresDropdown");if(m&&!e.target.closest(".features-menu"))m.classList.remove("open");const btn=e.target.closest("button");if(btn&&!btn.closest(".features-dropdown"))showClickFeedback(btn);else if(btn)showClickFeedback(btn);});
async function loadOnboarding(){try{const d=await api('/api/onboarding/status');const done=Number(d.completed||0),total=Number(d.total||0);$('onboardingStats').innerHTML=`<div class="stat"><span>Setup progress</span><b>${Number(d.percent||0)}%</b></div><div class="stat"><span>Plan</span><b>${esc(title(d.plan||'free'))}</b></div><div class="stat"><span>Products</span><b>${d.counts?.products||0}</b></div><div class="stat"><span>Customers</span><b>${d.counts?.customers||0}</b></div>`;$('onboardingProgress').textContent=`${done} of ${total} readiness checks completed.`;const actions={profile:['settings','Complete business profile'],logo:['settings','Add your business logo'],product:['inventory','Add your first product'],customer:['customers','Add your first customer'],branch:['branches','Set up a branch'],payment:['paymentHub','Configure receiving payments'],staff:['staff','Add a staff member'],plan:['plansPage','Review subscription plan']};$('onboardingChecklist').innerHTML=(d.checks||[]).map(x=>{const a=actions[x.id];const button=x.done?'':(a[0]===PAYMENT_HUB_PAGE_ID&&isNativeApp()?'':`<button class="link" onclick="showPage('${a[0]}')">${esc(a[1])} →</button>`);return `<div class="settings-note" style="display:flex;align-items:center;justify-content:space-between;gap:14px;margin:10px 0"><div><b>${x.done?'✓':'○'} ${esc(x.label)}</b><div class="muted">${x.done?'Completed':'Not completed yet'}</div></div>${button}</div>`}).join('');$('onboardingSnapshot').innerHTML=`<div class="settings-note">Products: <b>${d.counts?.products||0}</b><br>Customers: <b>${d.counts?.customers||0}</b><br>Branches: <b>${d.counts?.branches||0}</b><br>Active staff: <b>${d.counts?.staff||0}</b><br>Payment integrations: <b>${d.counts?.payment_integrations||0}</b></div>`;const next=(d.checks||[]).find(x=>!x.done);if(next){const a=actions[next.id];if(a[0]===PAYMENT_HUB_PAGE_ID&&isNativeApp()){$('onboardingNext').innerHTML=`<div class="insight"><b>${esc(next.label)}</b><br><span class="muted">Manage this from the BIGJOE website.</span></div>`}else{$('onboardingNext').innerHTML=`<div class="insight"><b>${esc(next.label)}</b><br><span class="muted">Completing this is the next recommended setup step.</span><br><button class="primary" style="margin-top:10px" onclick="showPage('${a[0]}')">${esc(a[1])}</button></div>`}}else $('onboardingNext').innerHTML='<div class="insight"><b>🎉 BIGJOE is fully set up.</b><br>Your main readiness checks are complete.</div>';}catch(e){toast(e.message,true)}}

