async function submitModal(e){
  e.preventDefault();
  const currentType=modalType,currentId=editingId;
  const saveBtn=$("modalSubmit");
  try{
    let endpoint,body;
    if(currentType==="product"){
      endpoint="/api/products"+(currentId?"/"+currentId:"");
      body={name:$("f_name").value,sku:$("f_sku").value,unit:$("f_unit").value,cost_price:Number($("f_cost").value),selling_price:Number($("f_sell").value),stock_quantity:Number($("f_stock").value),low_stock_level:Number($("f_low").value),batch_number:$("f_batch")?.value||"",expiry_date:$("f_expiry")?.value||"",category_id:$("f_cat").value||null,supplier_id:$("f_sup").value||null,description:$("f_desc").value,branch_id:$("f_branch")?.value||activeBranchId||null};
    }else if(currentType==="category"){
      endpoint="/api/categories"+(currentId?"/"+currentId:""); body={name:$("f_name").value,description:$("f_desc").value};
    }else if(currentType==="supplier"){
      endpoint="/api/suppliers"+(currentId?"/"+currentId:""); body={name:$("f_name").value,phone:$("f_phone").value,email:$("f_email").value,address:$("f_address").value};
    }else if(currentType==="customer"){
      endpoint="/api/customers"+(currentId?"/"+currentId:""); body={name:$("f_name").value,phone:$("f_phone").value,email:$("f_email").value,address:$("f_address").value};
      if(!String(body.name||"").trim())throw new Error("Customer name is required.");
      const fromPos=$("f_from_pos")?.value==="1";
      if(saveBtn){saveBtn.disabled=true;saveBtn.textContent="Saving…";}
      const d=await api(endpoint,{method:currentId?"PUT":"POST",body:JSON.stringify(body)});
      closeModal(); toast(currentId?"Customer updated successfully":"Customer added successfully"); await loadCustomers();
      if(fromPos&&!currentId&&$("customerSelect")){ $("customerSelect").value=d.customer.id; syncCustomerFields(); }
      return;
    }else if(currentType==="expense"){
      endpoint="/api/expenses"+(currentId?"/"+currentId:"");
      body={description:$("f_desc").value,category:$("f_exp_category").value,amount:Number($("f_amount").value),date:$("f_date").value,payment_method:$("f_exp_payment").value,notes:$("f_exp_notes").value,branch_id:$("f_exp_branch")?.value||activeBranchId||null};
    }else{return;}
    if(saveBtn){saveBtn.disabled=true;saveBtn.textContent="Saving…";}
    const d=await api(endpoint,{method:currentId?"PUT":"POST",body:JSON.stringify(body)});
    closeModal();
    const labels={product:"Product",category:"Category",supplier:"Supplier",expense:"Expense"};
    toast(`${labels[currentType]||"Record"} ${currentId?"updated":"added"} successfully.`);
    if(currentType==="expense") await loadExpenses();
    else await loadInventory();
  }catch(e){toast(e.message||"Unable to save this record.",true)}
  finally{if(saveBtn){saveBtn.disabled=false;saveBtn.textContent="Save";}}
}
