function printFinancialCenter(){const d=window.__financialCenterData;if(!d)return;const w=window.open('','_blank','width=1000,height=850');if(!w)return;const s=d.summary||{};w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Financial Intelligence Centre</title><style>body{font-family:Arial;color:#172033;max-width:900px;margin:30px auto;padding:20px}h1,h2{margin-bottom:6px}.muted{color:#667085}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.box{border:1px solid #ddd;border-radius:10px;padding:15px;margin:15px 0}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:left}.total{font-weight:800;border-top:2px solid #172033}@media print{button{display:none}}</style></head><body>${reportBrandHeader()}<h1>FINANCIAL INTELLIGENCE CENTRE</h1><p class="muted">${esc(d.period.start)} to ${esc(d.period.end)} • Prepared for ${esc(reportOwnerName())}</p><div class="grid"><div class="box"><h2>Profit & Loss</h2><table>${financialRow('Revenue',s.revenue)}${financialRow('Cost of goods sold',s.cogs)}${financialRow('Gross profit',s.gross_profit)}${financialRow('Operating expenses',s.operating_expenses)}${financialRow('Net profit / loss',s.net_profit,'total')}</table></div><div class="box"><h2>Cash Movement</h2><table>${financialRow('Cash inflow',s.cash_in)}${financialRow('Cash outflow',s.cash_out)}${financialRow('Net cash movement',s.net_cash,'total')}</table></div></div><div class="box"><h2>Working Capital</h2><table>${financialRow('Customer receivables',s.receivables)}${financialRow('Inventory value',s.inventory_value)}${financialRow('Supplier payables',s.payables)}${financialRow('Working capital',s.working_capital,'total')}</table></div><p style="text-align:center;margin-top:35px">Powered by BIGJOE Business AI</p><button onclick="window.print()">Print / Save as PDF</button></body></html>`);w.document.close();setTimeout(()=>w.print(),250)}
function exportFinancialCenterCSV(){const d=window.__financialCenterData;if(!d)return;const s=d.summary||{};const rows=[['BIGJOE Financial Intelligence Centre'],['Period',d.period.start,d.period.end],[],['Metric','Amount'],['Revenue',s.revenue],['Cost of goods sold',s.cogs],['Gross profit',s.gross_profit],['Operating expenses',s.operating_expenses],['Net profit / loss',s.net_profit],['Cash inflow',s.cash_in],['Cash outflow',s.cash_out],['Net cash movement',s.net_cash],['Customer receivables',s.receivables],['Supplier payables',s.payables],['Inventory value',s.inventory_value],['Working capital',s.working_capital]];const csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`BIGJOE_Financial_Centre_${d.period.start}_to_${d.period.end}.csv`;a.click();URL.revokeObjectURL(a.href)}


async function loadAutomationCenter(){try{
 const d=await api('/api/automation-center'); const s=d.summary||{};
 $('automationStats').innerHTML=`<div class="stat automation-stat"><span>Revenue · 7 days</span><b class="stat-value">${money(s.revenue)}</b></div><div class="stat automation-stat"><span>Gross profit · 7 days</span><b class="stat-value">${money(s.gross_profit)}</b></div><div class="stat automation-stat ${Number(s.expenses)>0?'danger':''}"><span>Expenses · 7 days</span><b class="stat-value">${money(s.expenses)}</b></div><div class="stat automation-stat"><span>Sales · 7 days</span><b class="stat-value">${Number(s.sales_count||0).toLocaleString()}</b></div>`;
 $('automationTimestamp').textContent='Updated '+new Date(d.generated_at||Date.now()).toLocaleTimeString('en-NG',{hour:'2-digit',minute:'2-digit'});
 $('automationBriefing').textContent=d.briefing||'No briefing is available yet.';
 $('automationAlerts').innerHTML=(d.alerts||[]).map(x=>`<div class="alert-item alert-${esc(x.level==='danger'?'high':x.level==='positive'?'positive':'medium')}"><b>${x.level==='danger'?'🔴':x.level==='warning'?'🟠':'🟢'} ${esc(x.title)}</b><span>${esc(x.text)}</span></div>`).join('');
 $('automationActions').innerHTML=(d.actions||[]).map(x=>`<div class="decision-card priority-${esc(x.priority)}"><div class="decision-card-top"><span class="decision-priority">${esc(title(x.priority))}</span></div><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p><button class="link" onclick="showPage('${esc(x.page)}',this)">Open related feature →</button></div>`).join('');
 const rows=(d.reorder||[]).map(x=>`<tr><td><b>${esc(x.name)}</b><small>${esc(x.sku||'')}</small></td><td>${x.stock}</td><td>${x.reorder_level}</td><td>${x.daily_demand}</td><td>${x.cover_days===null?'—':x.cover_days+' days'}</td><td><span class="planner-priority ${x.urgency==='urgent'?'critical':x.urgency==='high'?'high':'watch'}">${esc(title(x.urgency))}</span></td><td><b>${x.suggested_quantity}</b></td></tr>`).join('');
 $('automationReorder').innerHTML=rows?`<table><thead><tr><th>Product</th><th>Stock</th><th>Reorder level</th><th>Daily demand</th><th>Stock cover</th><th>Urgency</th><th>Suggested qty.</th></tr></thead><tbody>${rows}</tbody></table>`:'<div class="empty">No immediate reorder recommendation. Continue monitoring stock.</div>';
 const c=d.recent_changes||{}; const pctText=v=>v===null||v===undefined?'—':(Number(v)>=0?'↑ ':'↓ ')+Math.abs(Number(v)).toFixed(1)+'%';
 $('automationChanges').innerHTML=`<div class="snapshot-row"><span>Revenue vs prior 7 days</span><b>${pctText(s.revenue_change)}</b></div><div class="snapshot-row"><span>Profit vs prior 7 days</span><b>${pctText(s.profit_change)}</b></div><div class="snapshot-row"><span>Expenses vs prior 7 days</span><b>${pctText(s.expense_change)}</b></div><div class="snapshot-row"><span>Previous revenue</span><b>${money(c.previous_revenue||0)}</b></div>`;
}catch(e){toast(e.message,true)}}

async function loadSmartActions(){
  try{
    const [a,d]=await Promise.all([api('/api/smart-actions'),api('/api/decision-automation')]);
    const c=a.counts||{};
    $('smartActionStats').innerHTML=`<div class="stat"><span>Open Tasks</span><b>${a.open_tasks||0}</b></div><div class="stat"><span>Urgent</span><b>${c.urgent||0}</b></div><div class="stat"><span>In Progress</span><b>${c.in_progress||0}</b></div><div class="stat"><span>Completed</span><b>${c.completed||0}</b></div>`;
    const rec=d.top_decisions||[];
    const recCard=x=>`<div class="decision-card priority-${esc(x.priority)}"><div class="decision-card-top"><span class="decision-priority">${esc(title(x.priority))}</span><span class="decision-score">${Number(x.score||0)}/100</span></div><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p><div class="decision-next"><b>Next:</b> ${esc(x.next_step)}</div><small>${esc(x.reason)}</small><button class="primary compact-action" onclick='createTaskFromDecision(${JSON.stringify(x).replace(/'/g,"&#39;")})'>+ Create Task</button></div>`;
    $('smartRecommendedActions').innerHTML=rec.length?rec.map(recCard).join(''):'<div class="empty">No new recommendations right now.</div>';
    const open=(a.tasks||[]).filter(x=>!['completed','cancelled'].includes(x.status));
    $('smartOpenTasks').innerHTML=open.length?open.slice(0,10).map(taskMini).join(''):'<div class="empty">No open tasks. Excellent!</div>';
    const rows=(a.tasks||[]).map(task=>`<tr><td><b>${esc(task.title)}</b><small>${esc(task.category||'General')}</small></td><td><span class="badge task-${esc(task.priority)}">${esc(title(task.priority))}</span></td><td><span class="badge">${esc(title(task.status).replaceAll('_',' '))}</span></td><td>${esc(task.due_date||'—')}</td><td><button class="link" onclick="setSmartTaskStatus('${task.id}','${task.status==='completed'?'pending':task.status==='pending'?'in_progress':'completed'}')">${task.status==='completed'?'Reopen':task.status==='pending'?'Start':'Complete'}</button> <button class="danger-link" onclick="deleteSmartTask('${task.id}')">Delete</button></td></tr>`).join('');
    $('smartAllTasks').innerHTML=rows?`<table><thead><tr><th>Task</th><th>Priority</th><th>Status</th><th>Due</th><th>Actions</th></tr></thead><tbody>${rows}</tbody></table>`:'<div class="empty">No tasks created yet.</div>';
  }catch(e){toast(e.message,true)}
}
function taskMini(t){return `<div class="smart-task-item priority-${esc(t.priority)}"><div><b>${esc(t.title)}</b><small>${esc(t.category||'General')} · ${t.due_date?`Due ${esc(t.due_date)}`:'No due date'}</small></div><div class="smart-task-buttons"><button class="link" onclick="setSmartTaskStatus('${t.id}','${t.status==='pending'?'in_progress':'completed'}')">${t.status==='pending'?'Start':'Complete'}</button></div></div>`}
async function createSmartTask(payload={}){try{const b=Object.keys(payload).length?payload:{title:$('smartTaskTitle').value,priority:$('smartTaskPriority').value,due_date:$('smartTaskDue').value,category:$('smartTaskCategory').value,description:$('smartTaskDescription').value};if(!String(b.title||'').trim())return toast('Enter a task title.',true);await api('/api/smart-actions/tasks',{method:'POST',body:JSON.stringify(b)});if($('smartTaskTitle')){$('smartTaskTitle').value='';$('smartTaskDescription').value='';$('smartTaskDue').value='';}toast('Business task created successfully.');loadSmartActions()}catch(e){toast(e.message,true)}}
function createTaskFromDecision(x){const due=new Date(Date.now()+(x.priority==='urgent'?0:x.priority==='high'?86400000:3*86400000)).toISOString().slice(0,10);createSmartTask({title:x.title,description:`${x.text}\n\nNext step: ${x.next_step}\n\nEvidence: ${x.reason}`,priority:x.priority,due_date:due,category:x.category||'General',source_decision_id:x.id})}
async function setSmartTaskStatus(id,status){try{await api('/api/smart-actions/tasks/'+id,{method:'PUT',body:JSON.stringify({status})});toast(status==='completed'?'Task completed.':'Task status updated.');loadSmartActions()}catch(e){toast(e.message,true)}}
async function deleteSmartTask(id){if(!confirm('Delete this task?'))return;try{await api('/api/smart-actions/tasks/'+id,{method:'DELETE'});toast('Task deleted.');loadSmartActions()}catch(e){toast(e.message,true)}}

function setReportPreset(type){const now=new Date();let start=new Date(now),end=new Date(now);if(type==='today'){start=new Date(now.getFullYear(),now.getMonth(),now.getDate())}else if(type==='7'){start=new Date(now);start.setDate(now.getDate()-6)}else if(type==='month'){start=new Date(now.getFullYear(),now.getMonth(),1)}else if(type==='year'){start=new Date(now.getFullYear(),0,1)}if($('reportStart'))$('reportStart').value=start.toISOString().slice(0,10);if($('reportEnd'))$('reportEnd').value=end.toISOString().slice(0,10);return loadDashboard()}
function setReportPresetSilent(){const now=new Date();const start=new Date(now.getFullYear(),now.getMonth(),1);if($('reportStart'))$('reportStart').value=start.toISOString().slice(0,10);if($('reportEnd'))$('reportEnd').value=now.toISOString().slice(0,10)}

function setReportRange(days=30){const end=new Date();const start=new Date(end.getTime()-(days-1)*86400000);if($('reportEnd'))$('reportEnd').value=localDateKey(end);if($('reportStart'))$('reportStart').value=localDateKey(start);if($('dashboard')&&!$('dashboard').classList.contains('hidden'))loadDashboard()}

async function loadDecisionAutomation(){
  try{
    const d=await api('/api/decision-automation');
    const s=d.summary||{}, pc=d.priority_counts||{};
    $('decisionAutomationStats').innerHTML=`<div class="stat"><span>30-Day Revenue</span><b>${money(s.revenue)}</b></div><div class="stat ${Number(s.profit)<0?'danger':''}"><span>30-Day Gross Profit</span><b>${money(s.profit)}</b></div><div class="stat"><span>30-Day Expenses</span><b>${money(s.expenses)}</b></div><div class="stat"><span>Sales Momentum</span><b>${Number(s.weekly_change)>=0?'↑':'↓'} ${Math.abs(Number(s.weekly_change||0)).toFixed(1)}%</b></div>`;
    const card=x=>`<div class="decision-card priority-${esc(x.priority)}"><div class="decision-card-top"><span class="decision-priority">${x.priority==='urgent'?'🔴 URGENT':x.priority==='high'?'🟠 HIGH':'🟡 MEDIUM'}</span><span class="decision-score">Score ${Number(x.score||0)}</span></div><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p><div class="decision-next"><b>Next step:</b> ${esc(x.next_step)}</div><small><b>Why:</b> ${esc(x.reason)}</small></div>`;
    $('decisionTop').innerHTML=(d.top_decisions||[]).map(card).join('')||'<div class="empty">No recommendations yet.</div>';
    $('decisionUrgent').innerHTML=(d.decisions||[]).filter(x=>x.priority==='urgent').map(card).join('')||'<div class="empty">No urgent decisions detected.</div>';
    $('decisionHigh').innerHTML=(d.decisions||[]).filter(x=>x.priority==='high').map(card).join('')||'<div class="empty">No high-priority actions detected.</div>';
    $('decisionMedium').innerHTML=(d.decisions||[]).filter(x=>x.priority==='medium').map(card).join('')||'<div class="empty">No medium-priority actions detected.</div>';
    $('decisionPlan').innerHTML=(d.execution_plan||[]).map(x=>`<div class="execution-item"><span>${esc(x.when)}</span><b>${esc(x.title)}</b><small>${esc(x.next_step)}</small></div>`).join('')||'<div class="empty">No execution plan available.</div>';
    $('decisionEvidence').innerHTML=`<div class="evidence-grid"><div><span>Recent sales</span><b>${Number(d.data_quality?.recent_sales||0)}</b></div><div><span>Customer-linked sales</span><b>${Number(d.data_quality?.customer_linked_sales||0)}</b></div><div><span>Products tracked</span><b>${Number(d.data_quality?.products||0)}</b></div><div><span>Suppliers tracked</span><b>${Number(d.data_quality?.suppliers||0)}</b></div><div><span>Revenue change</span><b class="${Number(s.revenue_change)>=0?'positive':'negative'}">${Number(s.revenue_change)>=0?'↑':'↓'} ${Math.abs(Number(s.revenue_change||0)).toFixed(1)}%</b></div><div><span>Expense change</span><b class="${Number(s.expense_change)<=0?'positive':'negative'}">${Number(s.expense_change)>=0?'↑':'↓'} ${Math.abs(Number(s.expense_change||0)).toFixed(1)}%</b></div></div><p class="muted decision-footnote">${esc(d.note||'Recommendations are generated from recorded BIGJOE data.')}</p>`;
  }catch(e){toast(e.message,true)}
}
async function loadPredictiveIntelligence(){try{const d=await api('/api/predictive-intelligence');window.__predictiveData=d;const f=d.forecast||{},t=d.target||{};$('predictiveConfidence').textContent=`${f.confidence||'Low'} confidence`;$('predictiveStats').innerHTML=`<div class="stat"><span>Daily Forecast</span><b>${money(f.daily)}</b></div><div class="stat"><span>30-Day Base Forecast</span><b>${money(f.next_30_days)}</b></div><div class="stat ${Number(f.profit_estimate)<0?'danger':''}"><span>30-Day Profit Estimate</span><b>${money(f.profit_estimate)}</b></div><div class="stat"><span>Sales Momentum</span><b>${Number(f.momentum_pct)>=0?'↑':'↓'} ${Math.abs(Number(f.momentum_pct||0)).toFixed(1)}%</b></div>`;$('predictiveForecastCards').innerHTML=`<div class="forecast-card"><span>Lower Range</span><b>${money(f.next_30_days_low)}</b><small>30-day sales</small></div><div class="forecast-card"><span>Base Range</span><b>${money(f.next_30_days)}</b><small>30-day sales</small></div><div class="forecast-card"><span>Upper Range</span><b>${money(f.next_30_days_high)}</b><small>30-day sales</small></div>`;const mom=Number(f.momentum_pct||0);$('predictiveNarrative').innerHTML=`<b>BIGJOE outlook:</b> ${mom>10?'Sales momentum is improving.':mom<-10?'Sales momentum is weakening.':'Sales momentum is relatively stable.'} Based on the current pace, BIGJOE estimates about <b>${money(f.next_30_days)}</b> in sales over the next 30 days, with a planning range of <b>${money(f.next_30_days_low)}</b> to <b>${money(f.next_30_days_high)}</b>.`;$('predictiveTarget').innerHTML=t.monthly_target?`<div class="target-outlook"><b>${esc(t.likelihood)}</b><span>Current month: ${money(t.current_month_revenue)}</span><span>Projected month: ${money(t.projected_month_revenue)}</span><span>Target: ${money(t.monthly_target)}</span><small>${t.days_remaining} day(s) remaining</small></div>`:'<div class="empty">Set a monthly sales target in Business Planner to activate target forecasting.</div>';$('predictiveActions').innerHTML=(d.actions||[]).map((x,i)=>`<div class="insight"><b>${i+1}.</b> ${esc(x)}</div>`).join('');$('predictiveAlerts').innerHTML=(d.alerts||[]).map(x=>`<div class="alert-item alert-${esc(x.severity||'medium')}"><b>${x.severity==='high'?'⚠️':x.severity==='positive'?'✅':'🔔'} ${esc(x.title)}</b><span>${esc(x.text)}</span></div>`).join('');const rows=d.inventory_risk||[];$('predictiveInventory').innerHTML=rows.length?`<table><thead><tr><th>Product</th><th>Stock</th><th>60-Day Units</th><th>Daily Demand</th><th>Days Cover</th><th>Risk</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${Number(x.stock).toLocaleString()}</td><td>${Number(x.units_60d).toLocaleString()}</td><td>${Number(x.daily_rate).toFixed(2)}</td><td>${x.days_cover===null?'—':Number(x.days_cover).toFixed(1)}</td><td><span class="planner-priority ${esc(x.risk)}">${esc(x.risk)}</span></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No predictive stock risk detected from the available demand history.</div>';}catch(e){toast(e.message,true)}}
async function loadBusinessPlanner(){try{
 const d=await api('/api/business-planner');window.__businessPlannerData=d;const f=d.forecast||{},t=d.target||{},settings=d.settings||{};
 if($('plannerSalesTarget'))$('plannerSalesTarget').value=t.monthly_sales_target||'';if($('plannerExpenseLimit'))$('plannerExpenseLimit').value=t.monthly_expense_limit||'';if($('plannerLeadDays'))$('plannerLeadDays').value=settings.default_lead_days||7;if($('plannerSafetyDays'))$('plannerSafetyDays').value=settings.safety_stock_days||7;
 $('forecastConfidence').textContent=`${f.confidence||'Low'} confidence`;
 $('forecastCards').innerHTML=`<div class="forecast-card"><span>Next 7 Days</span><b>${money(f.next_7_days)}</b><small>Projected sales</small></div><div class="forecast-card"><span>Next 30 Days</span><b>${money(f.next_30_days)}</b><small>Projected sales</small></div><div class="forecast-card"><span>Daily Run Rate</span><b>${money(f.daily)}</b><small>Estimated average</small></div><div class="forecast-card"><span>Sales Momentum</span><b>${Number(f.trend_pct||0)>=0?'↑':'↓'} ${Math.abs(Number(f.trend_pct||0)).toFixed(1)}%</b><small>vs previous 7 days</small></div>`;
 const trend=Number(f.trend_pct||0);const narrative=trend>10?`Sales momentum is improving. If the current pace continues, BIGJOE projects about ${money(f.next_30_days)} in sales over the next 30 days.`:trend<-10?`Sales momentum is weakening. BIGJOE projects about ${money(f.next_30_days)} in the next 30 days, so focus on profitable sales and customer retention.`:`Sales momentum is relatively stable. BIGJOE projects about ${money(f.next_30_days)} in the next 30 days based on recent activity.`;$('forecastNarrative').innerHTML=`<b>BIGJOE forecast:</b> ${esc(narrative)}`;
 $('plannerStats').innerHTML=`<div class="stat"><span>Current Month Sales</span><b>${money(t.monthly_revenue)}</b></div><div class="stat"><span>Target</span><b>${t.monthly_sales_target?money(t.monthly_sales_target):'Not set'}</b></div><div class="stat"><span>Days Remaining</span><b>${t.days_remaining||0}</b></div><div class="stat"><span>Required Daily Pace</span><b>${t.required_daily?money(t.required_daily):'—'}</b></div>`;
 const tp=Number(t.sales_progress||0),ep=Number(t.expense_progress||0);$('plannerTargetProgress').innerHTML=t.monthly_sales_target?`<div class="progress-ring-row"><b>${tp.toFixed(1)}%</b><span>${money(t.monthly_revenue)} of ${money(t.monthly_sales_target)}</span></div><div class="planner-meter"><div style="width:${Math.min(100,tp)}%"></div></div><p class="muted">${t.required_daily?`Need about ${money(t.required_daily)} per day for the remaining ${t.days_remaining} day(s).`:'Target achieved or no additional daily pace required.'}</p>`:'<div class="empty">Set a monthly sales target to activate target tracking.</div>';$('plannerExpenseProgress').innerHTML=t.monthly_expense_limit?`<div class="progress-ring-row"><b>${ep.toFixed(1)}%</b><span>${money(t.monthly_expenses)} of ${money(t.monthly_expense_limit)}</span></div><div class="planner-meter expense-meter"><div style="width:${Math.min(100,ep)}%"></div></div><p class="muted">${ep>=100?'Expense limit has been reached or exceeded.':'Remaining budget: '+money(Math.max(0,t.monthly_expense_limit-t.monthly_expenses))}</p>`:'<div class="empty">Set an expense limit to monitor monthly spending.</div>';
 const rr=d.reorder_plan||[];$('reorderRecommendations').innerHTML=rr.length?`<table><thead><tr><th>Product</th><th>Stock</th><th>Daily Sales</th><th>Days Cover</th><th>Reorder Point</th><th>Recommended Qty</th><th>Priority</th></tr></thead><tbody>${rr.map(x=>`<tr><td><b>${esc(x.name)}</b><small>${esc(x.sku||'')}</small></td><td>${Number(x.stock).toLocaleString()}</td><td>${Number(x.daily_rate).toFixed(2)}</td><td>${x.days_cover===null?'—':Number(x.days_cover).toFixed(1)}</td><td>${Number(x.reorder_point).toFixed(1)}</td><td><b>${Number(x.recommended_qty).toLocaleString()}</b></td><td><span class="planner-priority ${esc(x.priority)}">${esc(x.priority)}</span><small>${esc(x.reason)}</small></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No immediate reorder recommendations. Keep recording sales so BIGJOE can improve its forecast.</div>';
 $('plannerTopProducts').innerHTML=(d.best_products||[]).map((x,i)=>dashboardRow(`${i+1}. ${x.name}`,money(x.revenue),`${Number(x.quantity).toLocaleString()} units sold in the last 30 days`)).join('')||'<div class="empty">No recent sales yet.</div>';$('plannerAlerts').innerHTML=(d.alerts||[]).map(x=>`<div class="alert-item alert-${esc(x.severity||'medium')}"><b>${x.severity==='high'?'⚠️':x.severity==='positive'?'✅':'🔔'} ${esc(x.title)}</b><span>${esc(x.text)}</span></div>`).join('');
 }catch(e){toast(e.message,true)}}
function budgetRowTemplate(category='',amount=''){return `<div class="budget-row"><input class="budget-category" placeholder="e.g. Transport" value="${esc(category)}"><input class="budget-amount" type="number" min="0" step="1000" placeholder="Budget (₦)" value="${amount||''}"><button class="danger-link" onclick="this.parentElement.remove()">Remove</button></div>`}
function addBudgetRow(category='',amount=''){const wrap=$('budgetRows');if(wrap)wrap.insertAdjacentHTML('beforeend',budgetRowTemplate(category,amount));}
async function loadBudgetControl(){try{const d=await api('/api/budget-control');window.__budgetControlData=d;const s=d.summary||{};const cls=Number(s.remaining)<0?'danger':'';$('budgetStats').innerHTML=`<div class="stat"><span>Month Expenses</span><b>${money(s.actual)}</b></div><div class="stat"><span>Effective Budget</span><b>${s.effective_budget?money(s.effective_budget):'Not set'}</b></div><div class="stat ${cls}"><span>Budget Remaining</span><b>${money(s.remaining)}</b></div><div class="stat"><span>Budget Used</span><b>${Number(s.progress||0).toFixed(1)}%</b></div>`;
const rows=d.categories||[];$('budgetTable').innerHTML=rows.length?`<table><thead><tr><th>Category</th><th>Budget</th><th>Actual</th><th>Remaining</th><th>Used</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.category)}</b></td><td>${x.budget?money(x.budget):'—'}</td><td>${money(x.actual)}</td><td class="${x.variance<0?'negative-text':'positive-text'}">${money(x.variance)}</td><td>${Number(x.progress).toFixed(1)}%</td><td><span class="planner-priority ${esc(x.status==='over'?'urgent':x.status==='watch'?'watch':x.status==='unbudgeted'?'high':'healthy')}">${esc(x.status)}</span></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No expense categories found yet.</div>';
const months=d.recent_months||[];const max=Math.max(1,...months.map(x=>Number(x.amount||0)));$('budgetTrend').innerHTML=months.map(x=>{const w=Math.max(2,Number(x.amount||0)/max*100);return `<div class="bar-item" title="${x.month}: ${money(x.amount)}"><div class="bar-label">${new Date(x.month+'-01T00:00:00').toLocaleDateString('en-NG',{month:'short',year:'numeric'})}</div><div class="bar-track"><div class="bar-fill" style="width:${w}%"></div></div><div class="bar-value">${money(x.amount)}</div></div>`}).join('');
$('budgetAlerts').innerHTML=(d.alerts||[]).map(x=>`<div class="alert-item alert-${esc(x.severity||'medium')}"><b>${x.severity==='high'?'⚠️':x.severity==='positive'?'✅':'🔔'} ${esc(x.title)}</b><span>${esc(x.text)}</span></div>`).join('');
const over=rows.filter(x=>x.status==='over'),watch=rows.filter(x=>x.status==='watch'),unbudgeted=rows.filter(x=>x.status==='unbudgeted');const rec=[];if(over.length)rec.push(`Reduce or review spending in ${over.slice(0,3).map(x=>x.category).join(', ')} because the configured budget has already been exceeded.`);if(watch.length)rec.push(`Watch ${watch.slice(0,3).map(x=>x.category).join(', ')} closely; these categories are approaching their limits.`);if(unbudgeted.length)rec.push(`Consider setting budgets for ${unbudgeted.slice(0,3).map(x=>x.category).join(', ')} so BIGJOE can detect overruns earlier.`);if(!rec.length)rec.push(s.effective_budget?`Current spending is within the configured budget. Keep monitoring the ${Number(s.progress||0).toFixed(1)}% already used.`:'Set a monthly or category budget to activate cost-control recommendations.');$('budgetRecommendations').innerHTML=rec.map((x,i)=>`<div class="insight"><b>${i+1}.</b> ${esc(x)}</div>`).join('');
const wrap=$('budgetRows');if(wrap){wrap.innerHTML='';const configured=d.budgets||{};Object.entries(configured).forEach(([c,a])=>addBudgetRow(c,a));if(!Object.keys(configured).length)rows.slice(0,5).forEach(x=>addBudgetRow(x.category,''));} }catch(e){toast(e.message,true)}}
async function saveBudgetSettings(){try{const rows=[...document.querySelectorAll('.budget-row')].map(r=>({category:r.querySelector('.budget-category')?.value||'',amount:Number(r.querySelector('.budget-amount')?.value||0)})).filter(x=>x.category.trim()&&x.amount>0);const current=window.__budgetControlData?.summary||{};const monthly=prompt('Optional overall monthly expense limit (₦):',String(current.monthly_limit||''));let monthlyLimit=monthly===null?Number(current.monthly_limit||0):Math.max(0,Number(monthly||0));await api('/api/budget-control/settings',{method:'PUT',body:JSON.stringify({budgets:rows,monthly_expense_limit:monthlyLimit})});toast('Budget settings saved successfully.');await loadBudgetControl();}catch(e){toast(e.message,true)}}

async function loadCustomerIntelligence(){try{const d=await api('/api/customer-intelligence');const s=d.summary||{};
$('customerIntelStats').innerHTML=`<div class="stat"><span>Total Customers</span><b>${s.total_customers||0}</b></div><div class="stat"><span>Active Customers</span><b>${s.active_customers||0}</b></div><div class="stat"><span>Repeat Customers</span><b>${s.repeat_customers||0}</b></div><div class="stat"><span>Total Customer Sales</span><b>${money(s.total_revenue||0)}</b></div><div class="stat"><span>Average Customer Value</span><b>${money(s.average_customer_value||0)}</b></div>`;
$('repeatRate').innerHTML=`<b>${Number(s.repeat_rate||0).toFixed(1)}%</b><span>of customers have made more than one completed purchase.</span>`;
$('customerValue').innerHTML=`<b>${money(s.average_customer_value||0)}</b><span>average historical spend per customer.</span>`;
$('customerSegments').innerHTML=(d.segments||[]).map(x=>`<div class="segment-card"><b>${esc(x.name)}</b><strong>${x.count}</strong><span>${money(x.revenue)} sales</span><small>${esc(x.description)}</small></div>`).join('');
__custIntelCache.customers=d.customers||[];__custIntelCache.likely=d.likely_to_buy||[];
renderCustomerLeaderboard(false);renderLikelyToBuy(false);
$('customerProductInsights').innerHTML=(d.top_products||[]).map((x,i)=>dashboardRow(`${i+1}. ${x.name}`,money(x.revenue),`${x.quantity} units sold to ${x.customers} customer(s)`)).join('')||'<div class="empty">No customer-linked product sales yet.</div>';
$('customerActions').innerHTML=(d.actions||[]).map(x=>`<div class="insight"><b>${esc(x.title)}</b><span>${esc(x.text)}</span></div>`).join('')||'<div class="empty">No customer action is required right now.</div>';
}catch(e){toast(e.message,true)}}
// Leaderboard tables are capped to a short "top N" view by default instead of dumping every
// customer at once — that's what was making the Customer Intelligence page feel endless on a
// phone. The cached data avoids a refetch when someone taps "Show all".
let __custIntelCache={customers:[],likely:[]};
const LEADER_ROW_LIMIT=5;
function renderCustomerLeaderboard(expanded){
  const rows=__custIntelCache.customers,list=expanded?rows:rows.slice(0,LEADER_ROW_LIMIT);
  const table=rows.length?`<table><thead><tr><th>Customer</th><th>Orders</th><th>Total Spent</th><th>Avg Order</th><th>Last Purchase</th><th>Days Since</th><th>Segment</th></tr></thead><tbody>${list.map(x=>`<tr><td><b>${esc(x.name)}</b><small>${esc(x.phone||x.email||'')}</small></td><td>${x.orders}</td><td>${money(x.total_spent)}</td><td>${money(x.avg_order)}</td><td>${x.last_purchase||'—'}</td><td>${x.days_since_last===null?'—':x.days_since_last}</td><td><span class="segment-pill ${esc(x.segment_key)}">${esc(x.segment)}</span></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No customer sales history yet.</div>';
  const toggle=rows.length>LEADER_ROW_LIMIT?`<button type="button" class="table-expand-toggle" onclick="renderCustomerLeaderboard(${!expanded})">${expanded?`↑ Show top ${LEADER_ROW_LIMIT}`:`Show all ${rows.length} customers ↓`}</button>`:'';
  $('customerLeaderboard').innerHTML=`<div class="table-scroll">${table}</div>${toggle}`;
}
function renderLikelyToBuy(expanded){
  const rows=__custIntelCache.likely,list=expanded?rows:rows.slice(0,LEADER_ROW_LIMIT);
  const table=rows.length?`<table><thead><tr><th>Customer</th><th>Score</th><th>Last Purchase</th><th>Orders</th><th>Total Spent</th><th>Reason</th></tr></thead><tbody>${list.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td><span class="planner-priority ${x.score>=75?'healthy':x.score>=55?'watch':'high'}">${x.score}/100</span></td><td>${x.last_purchase||'—'}</td><td>${x.orders}</td><td>${money(x.total_spent)}</td><td><small>${esc(x.reason)}</small></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No returning-customer signal yet. Keep recording customer sales.</div>';
  const toggle=rows.length>LEADER_ROW_LIMIT?`<button type="button" class="table-expand-toggle" onclick="renderLikelyToBuy(${!expanded})">${expanded?`↑ Show top ${LEADER_ROW_LIMIT}`:`Show all ${rows.length} customers ↓`}</button>`:'';
  $('likelyToBuy').innerHTML=`<div class="table-scroll">${table}</div>${toggle}`;
}

async function savePlannerSettings(){try{await api('/api/business-planner/settings',{method:'PUT',body:JSON.stringify({monthly_sales_target:Number($('plannerSalesTarget').value||0),monthly_expense_limit:Number($('plannerExpenseLimit').value||0),default_lead_days:Number($('plannerLeadDays').value||7),safety_stock_days:Number($('plannerSafetyDays').value||7)})});toast('Planning settings saved successfully.');await loadBusinessPlanner();}catch(e){toast(e.message,true)}}


async function loadCashFlow(){try{const d=await api('/api/cashflow-forecast');window.__cashflowData=d;const risk=d.risk||'healthy';$('cashflowRisk').textContent=risk==='critical'?'⚠ Critical':risk==='watch'?'⚠ Watch':'✓ Stable';$('cashflowStats').innerHTML=`<div class="stat"><span>Current Cash Position</span><b>${money(d.current_cash)}</b></div><div class="stat"><span>30-Day Projected Closing</span><b class="${Number(d.projected_30_day_closing)<0?'negative-text':''}">${money(d.projected_30_day_closing)}</b></div><div class="stat"><span>Open Receivables</span><b>${money(d.open_receivables)}</b></div><div class="stat danger"><span>Open Payables</span><b>${money(d.open_payables)}</b></div>`;const f=d.forecast||[],max=Math.max(1,...f.map(x=>Math.abs(Number(x.closing||0))),Math.abs(Number(d.current_cash||0)));$('cashflowChart').innerHTML=f.map(x=>{const n=Number(x.closing||0),w=Math.max(2,Math.min(100,Math.abs(n)/max*100));return `<div class="bar-item" title="${x.date}: ${money(n)} projected closing cash"><div class="bar-label">${new Date(x.date+'T00:00:00').toLocaleDateString('en-NG',{day:'2-digit',month:'short'})}</div><div class="bar-track"><div class="bar-fill ${n<0?'negative':''}" style="width:${w}%"></div></div><div class="bar-value">${money(n)}</div></div>`}).join('');$('cashflowAlerts').innerHTML=(d.alerts||[]).map(x=>`<div class="alert-item alert-${esc(x.severity||'medium')}"><b>${x.severity==='high'?'⚠️':x.severity==='positive'?'✅':'🔔'} ${esc(x.title)}</b><span>${esc(x.text)}</span></div>`).join('');$('cashflowReceivables').innerHTML=(d.open_invoices||[]).map(x=>dashboardRow(x.number,money(x.outstanding),`${esc(x.customer_name||'Customer')} • due ${x.due_date||'not set'}`)).join('')||'<div class="empty">No outstanding customer invoices.</div>';$('cashflowPayables').innerHTML=(d.open_purchases||[]).map(x=>dashboardRow(x.number,money(x.outstanding),`${esc(x.supplier_name||'Supplier')} • due ${x.due_date||'not set'}`)).join('')||'<div class="empty">No outstanding supplier purchases.</div>';runCashScenario();}catch(e){toast(e.message,true)}}
function runCashScenario(){const d=window.__cashflowData;if(!d)return;const sales=Math.max(0,Number($('scenarioSales').value||0)),margin=Math.max(0,Math.min(100,Number($('scenarioMargin').value||0))),expenses=Math.max(0,Number($('scenarioExpenses').value||0)),oneTime=Math.max(0,Number($('scenarioCost').value||0));const gross=sales*margin/100,net=gross-expenses-oneTime;const projected=Number(d.projected_30_day_closing||0)+net;$('scenarioResult').innerHTML=`<div class="scenario-card"><div><span>Extra gross profit</span><b>${money(gross)}</b></div><div><span>Scenario net cash impact</span><b class="${net<0?'negative-text':'positive-text'}">${net>=0?'+':''}${money(net)}</b></div><div><span>Estimated closing cash</span><b class="${projected<0?'negative-text':''}">${money(projected)}</b></div><p>${net>=0?'This scenario would improve projected cash based on the assumptions entered.':'This scenario would reduce projected cash. Review the margin, extra expenses or one-time cost before proceeding.'}</p></div>`}

function dashboardRow(name,value,extra=''){return `<div class="dash-row"><div><b>${esc(name)}</b>${extra?`<small>${esc(extra)}</small>`:''}</div><strong>${value}</strong></div>`}
function setAnalyticsPreset(type){
 const now=new Date(); let start=new Date(now), end=new Date(now);
 if(type==='today')start=new Date(now.getFullYear(),now.getMonth(),now.getDate());
 else if(type==='7')start.setDate(now.getDate()-6);
 else if(type==='month'){start=new Date(now.getFullYear(),now.getMonth(),1);}
 else if(type==='year'){start=new Date(now.getFullYear(),0,1);}
 $('analyticsStart').value=start.toISOString().slice(0,10); $('analyticsEnd').value=end.toISOString().slice(0,10); loadAnalytics();
}
function analyticsChange(n){n=Number(n||0);return `<span class="change ${n>0?'up':n<0?'down':'flat'}">${n>0?'↑':n<0?'↓':'→'} ${Math.abs(n).toFixed(1)}%</span>`}
