 const c=d.comparison||{};
 $('analyticsComparison').innerHTML=`<div><span>Revenue</span><b>${money(c.revenue)} ${analyticsChange(c.revenue_change)}</b></div><div><span>Gross Profit</span><b>${money(c.gross_profit)} ${analyticsChange(c.profit_change)}</b></div><div><span>Expenses</span><b>${money(c.expenses)} ${analyticsChange(c.expense_change)}</b></div><div><span>Net Profit</span><b>${money(c.net_profit)} ${analyticsChange(c.net_profit_change)}</b></div>`;
 const daily=d.daily||[],max=Math.max(1,...daily.map(x=>Math.max(Number(x.revenue||0),Number(x.gross_profit||0),Number(x.expenses||0),Math.abs(Number(x.net_profit||0)))));
 $('analyticsTrend').innerHTML=daily.map(x=>{const vals=[['Revenue',Number(x.revenue||0),''],['Gross',Number(x.gross_profit||0),'profit-fill'],['Expenses',Number(x.expenses||0),''],['Net',Number(x.net_profit||0),`profit-fill ${Number(x.net_profit)<0?'negative':''}`]];return `<div class="analytics-day"><div class="bar-label">${new Date(x.date+'T00:00:00').toLocaleDateString('en-NG',{day:'2-digit',month:'short'})}</div>${vals.map(v=>`<div class="bar-item mini"><span class="mini-label">${v[0]}</span><div class="bar-track"><div class="bar-fill ${v[2]}" style="width:${Math.max(2,Math.abs(v[1])/max*100)}%"></div></div><div class="bar-value">${money(v[1])}</div></div>`).join('')}</div>`}).join('')||'<div class="empty">No data in this period.</div>';
 $('analyticsCategories').innerHTML=(d.categories||[]).length?`<table><thead><tr><th>Category</th><th>Units</th><th>Revenue</th><th>Profit</th><th>Margin</th></tr></thead><tbody>${d.categories.map(x=>`<tr><td><b>${esc(x.category)}</b></td><td>${Number(x.units).toLocaleString()}</td><td>${money(x.revenue)}</td><td>${money(x.profit)}</td><td>${Number(x.margin).toFixed(1)}%</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No category sales data.</div>';
 $('analyticsBranches').innerHTML=(d.branches||[]).length?`<table><thead><tr><th>Branch</th><th>Sales</th><th>Revenue</th><th>Profit</th><th>Net</th></tr></thead><tbody>${d.branches.map(x=>`<tr><td><b>${esc(x.branch_name)}</b></td><td>${x.sales}</td><td>${money(x.revenue)}</td><td>${money(x.profit)}</td><td>${money(x.net_profit)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No branch activity in this period.</div>';
 $('analyticsCustomers').innerHTML=(d.customers||[]).length?`<table><thead><tr><th>Customer</th><th>Orders</th><th>Total Spent</th><th>Avg Order</th></tr></thead><tbody>${d.customers.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${x.orders}</td><td>${money(x.total)}</td><td>${money(x.avg_order)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No customer-linked sales in this period.</div>';
 $('analyticsSuppliers').innerHTML=(d.suppliers||[]).length?`<table><thead><tr><th>Supplier</th><th>Orders</th><th>Total</th><th>Received</th></tr></thead><tbody>${d.suppliers.map(x=>`<tr><td><b>${esc(x.supplier_name)}</b></td><td>${x.orders}</td><td>${money(x.total)}</td><td>${Number(x.received_rate).toFixed(1)}%</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No supplier purchases in this period.</div>';
 $('analyticsPayments').innerHTML=(d.payment_methods||[]).map(x=>dashboardRow(x.method,money(x.total))).join('')||'<div class="empty">No payment data.</div>';
 $('analyticsStockRisk').innerHTML=(d.stock_risk||[]).map(x=>`<div class="dash-row insight-row risk-${esc(x.risk)}"><div><b>${esc(x.name)}</b><small>${Number(x.stock).toLocaleString()} in stock • Minimum ${Number(x.minimum).toLocaleString()} • ${x.days_cover===null?'No sales rate':Number(x.days_cover).toFixed(1)+' days cover'}</small></div><b>${x.risk==='critical'?'Reorder now':x.risk==='high'?'High risk':'Watch'}</b></div>`).join('')||'<div class="empty">No stock-risk products detected.</div>';
