 $('bestProducts').innerHTML=(d.best_products||[]).map((x,i)=>dashboardRow(`${i+1}. ${x.name}`,`${Number(x.quantity).toLocaleString()} sold`,`${money(x.revenue)} revenue • ${money(x.profit)} profit`)).join('')||'<div class="empty">No product sales in this period.</div>';
 $('topCustomers').innerHTML=(d.top_customers||[]).map((x,i)=>dashboardRow(`${i+1}. ${x.name}`,money(x.total),`${x.purchases} purchase${x.purchases===1?'':'s'}`)).join('')||'<div class="empty">No customer sales in this period.</div>';
 $('paymentMethods').innerHTML=(d.payment_methods||[]).map(x=>dashboardRow(title(x.method),money(x.total))).join('')||'<div class="empty">No payment data.</div>';
