 $('dashboardLowStock').innerHTML=(d.low_stock||[]).map(x=>dashboardRow(x.name,`${Number(x.stock).toLocaleString()} ${esc(x.unit)}`,`Minimum level: ${Number(x.level).toLocaleString()} • ${esc(x.sku||'No SKU')}`)).join('')||'<div class="empty">No low-stock products. Your inventory looks healthy.</div>';
 const margin=s.revenue?((s.profit/s.revenue)*100):0, netMargin=s.revenue?((s.net_profit/s.revenue)*100):0;
 let insights=[];
 if(s.sales===0) insights.push('No completed sales were recorded in the selected period.');
 else if(s.net_profit<0) insights.push('Net profit is negative. Review operating expenses and product margins before increasing spending.');
 else insights.push(`Net profit is ${money(s.net_profit)}, giving a ${netMargin.toFixed(1)}% net margin on revenue.`);
 if((d.best_products||[])[0]) insights.push(`${d.best_products[0].name} is the best-selling product by units in this period.`);
 if((d.expense_categories||[])[0]) insights.push(`${d.expense_categories[0].category} is the largest expense category at ${money(d.expense_categories[0].total)}.`);
 if((d.low_stock||[]).length) insights.push(`${d.low_stock.length} product${d.low_stock.length===1?'':'s'} need stock attention.`); else insights.push('Inventory currently has no low-stock alerts.');
 if(Number(s.expense_ratio||0)>30) insights.push(`Operating expenses consume ${Number(s.expense_ratio).toFixed(1)}% of revenue. Watch discretionary spending.`);
