function renderPlans(planMap){
  const plansRoot=$("plans");
  if(!plansRoot)return;
  const fallback={
    free:{name:"Free Forever",amount:0,currency:"NGN"},
    business:{name:"Business",amount:1500,currency:"NGN"},
    pro:{name:"Pro",amount:3000,currency:"NGN"}
  };
  const source=planMap||{};
  const plans={...fallback};
  const recurring=window.__bigjoeRecurringPlans||{};
  ["free","business","pro"].forEach(k=>{if(source[k])plans[k]={...fallback[k],...source[k],name:source[k].name||fallback[k].name,amount:Number(source[k].amount??fallback[k].amount),currency:source[k].currency||"NGN"};});
  const local={
    free:["Core business dashboard","Sales / POS","Inventory & customers","Basic AI Assistant"],
    business:["Everything in Free Forever","Advanced analytics & reports","Branches and business controls","Priority business tools"],
    pro:["Everything in Business","Advanced AI & automation","Premium intelligence & controls","Priority support"]
  };
  const expiresAt=user?.subscription_expires_at?new Date(user.subscription_expires_at):null;
  const daysLeft=expiresAt?Math.ceil((expiresAt.getTime()-Date.now())/86400000):null;
  const expired=user?.subscription_status==='expired' && user?.subscription_plan;
  const expiredBanner=expired?`<div class="settings-note plan-expired-banner"><b>⚠ Your ${esc(title(user.subscription_plan))} plan expired${user.subscription_expires_at?` on ${new Date(user.subscription_expires_at).toLocaleDateString('en-NG')}`:''}.</b> You're back on Free Forever until you renew. <button type="button" class="plan-button flutterwave-button" style="margin-top:8px" onclick="pay('${user.subscription_plan}')">Renew ${esc(title(user.subscription_plan))} for one month</button></div>`:'';
  plansRoot.innerHTML=expiredBanner+["free","business","pro"].map(k=>{
    const p=plans[k],current=String(k)===String(user?.plan||""),paid=k!=="free",popular=k==="business";
    const amount=Number(p.amount||0);
    const price=amount===0?"₦0":`₦${amount.toLocaleString("en-NG")}`;
    const features=Array.isArray(p.features)&&p.features.length?p.features:local[k];
    const previouslyExpired=!current && paid && expired && String(user.subscription_plan)===k;
    let action;
    if(current && paid) action=`<button type="button" class="plan-button flutterwave-button" onclick="pay('${k}')">Renew for another month</button>`;
    else if(current) action='<button class="plan-button current-button" disabled>✓ Current plan</button>';
    else if(previouslyExpired) action=`<button type="button" class="plan-button flutterwave-button" onclick="pay('${k}')">Renew ${esc(p.name)}</button>`;
    else if(paid) action=`<button type="button" class="plan-button flutterwave-button" onclick="pay('${k}')">Subscribe with Flutterwave</button>`;
    else action='<button type="button" class="plan-button free-button" onclick="selectFreePlan()">Start Free Forever</button>';
    let expiryNote='';
    if(current && paid && expiresAt) expiryNote=`<div class="subscription-point">${daysLeft!==null&&daysLeft<=7?'⚠ ':''}<b>${daysLeft!==null&&daysLeft>=0?`Renews/expires in ${daysLeft} day${daysLeft===1?'':'s'}`:'Expires'}:</b> ${expiresAt.toLocaleDateString('en-NG')}</div>`;
    else if(previouslyExpired) expiryNote=`<div class="subscription-point">⚠ <b>Expired${user.subscription_expires_at?` on ${new Date(user.subscription_expires_at).toLocaleDateString('en-NG')}`:''}.</b> Renew to restore access.</div>`;
    return `<article class="plan plan-card ${popular?'plan-popular':''} ${current?'plan-current':''}">
      ${popular?'<div class="plan-ribbon">MOST POPULAR</div>':''}
      <div class="plan-card-top"><span class="plan-label">${esc(p.name)}</span>${current?'<span class="plan-current-badge">CURRENT</span>':''}</div>
      <div class="plan-price">${price}<small>${k==="free"?"forever":"/ month"}</small></div>
      <div class="subscription-point"><b>Subscription:</b> ${k==="free"?"Free Forever":`${price} per month via Flutterwave, renews every 1 month`}</div>
      ${expiryNote}
      <p class="plan-description">${k==="free"?"Start managing your business with no monthly subscription.":k==="business"?"The balanced plan for growing businesses that need more control.":"The complete BIGJOE experience for businesses ready to scale."}</p>
      <ul class="plan-features">${(features||[]).map(x=>`<li>✓ ${esc(x)}</li>`).join("")}</ul>
      <div class="plan-action">${action}${paid?`<small class="payment-note">Secure Flutterwave checkout${recurring[k]?' • recurring billing ready when configured':' • one month per payment, renew anytime'}</small>`:''}</div>
    </article>`;
  }).join("");
}
function selectFreePlan(){toast("You are on the Free Forever plan. Start using BIGJOE without a subscription.");}
async function loadPlans(){
  const fallback={free:{name:"Free Forever",amount:0,currency:"NGN"},business:{name:"Business",amount:1500,currency:"NGN"},pro:{name:"Pro",amount:3000,currency:"NGN"}};
  renderPlans(fallback);
  const status=$('plansPaymentStatus');
  if(status) status.innerHTML='<b>Flutterwave:</b> checking secure checkout connection…';
  try{
    const remote=await api('/api/plans');
    if(user){
      if(remote?.current_plan) user.plan=remote.current_plan;
      user.subscription_status=remote?.subscription_status||user.subscription_status;
      user.subscription_plan=remote?.subscription_plan||user.subscription_plan;
      user.subscription_expires_at=remote?.subscription_expires_at||null;
    }
    if(remote?.plans){ window.__bigjoeRecurringPlans=remote.recurring_available||{}; renderPlans({...fallback,...remote.plans}); }
    applyPlanUI();
    if(status){
      const g=remote?.subscription_gateway||{};
      status.innerHTML=g.configured?`<span class="payment-status-ok">✓ <b>BIGJOE subscription checkout is configured.</b> Subscription checkout is connected to your BIGJOE Flutterwave account.</span>`:`<span class="payment-status-warn">⚠ <b>Subscription checkout is not configured.</b> Configure Flutterwave in Payment Hub or add the BIGJOE subscription key to .env.</span>`;
    }
  }catch(e){
    console.warn('BIGJOE plans API unavailable; keeping built-in subscription definitions.',e);
    if(status) status.innerHTML='<span class="payment-status-warn">⚠ Flutterwave status could not be checked. You can configure it from Payment Hub.</span>';
  }
}

async function loadPaymentHub(){try{const d=await api('/api/payments/hub');const p=d.providers||{};const s=d.summary||{};$('paymentProviderStats').innerHTML=`<div class="stat"><span>Total Gateway Records</span><b>${s.total||0}</b></div><div class="stat"><span>Successful</span><b>${s.successful||0}</b></div><div class="stat"><span>Pending</span><b>${s.pending||0}</b></div><div class="stat danger"><span>Unreconciled</span><b>${s.unreconciled||0}</b></div>`;const card=(x,name)=>`<div class="settings-note"><b>${name} receiving account</b><br>Status: ${x.configured?'Configured for '+(x.mode||'test').toUpperCase()+' mode':'Not configured yet'}<br>${x.account_name?`Account: ${esc(x.account_name)}<br>`:''}<span class="muted">Your receiving credentials are separate from BIGJOE subscription credentials and are never displayed in full.</span></div>`;$('flutterwaveCard').innerHTML=card(p.flutterwave,'Flutterwave');$('paystackCard').innerHTML=card(p.paystack,'Paystack');$('flutterwaveStatus').textContent=p.flutterwave.configured?'Receiving account configured.':'Configure your Flutterwave receiving account.';$('paystackStatus').textContent=p.paystack.configured?'Receiving account configured.':'Configure your Paystack receiving account.';$('paymentReconciliationSummary').innerHTML=`<div class="settings-note"><b>${s.unreconciled||0}</b> successful payment(s) still need reconciliation.</div>`;const rows=(d.transactions||[]).map(x=>`<tr><td><b>${esc(x.tx_ref||x.id||'—')}</b></td><td>${esc(title(x.plan||x.provider||'Payment'))}</td><td>${money(x.amount||0)}</td><td>${esc(x.currency||'NGN')}</td><td>${esc(title(x.status||'unknown'))}</td><td>${x.reconciliation_status==='reconciled'?'<span class="badge">✓ Reconciled</span>':'<span class="badge">Needs review</span>'}</td><td>${x.status==='successful'&&x.reconciliation_status!=='reconciled'?`<button class="link" onclick="reconcilePayment('${x.id}')">Reconcile</button>`:'—'}</td></tr>`).join('');$('paymentHubTable').innerHTML=rows?`<table><thead><tr><th>Reference</th><th>Type</th><th>Amount</th><th>Currency</th><th>Status</th><th>Reconciliation</th><th>Action</th></tr></thead><tbody>${rows}</tbody></table>`:'<div class="empty">No gateway payment records yet.</div>'}catch(e){toast(e.message,true)}}
async function openPaymentConfig(provider){try{const d=await api('/api/payments/receiving/config');const x=d[provider]||{};$('paymentConfigProvider').value=provider;$('paymentConfigTitle').textContent=`Configure ${title(provider)} for Customer Payments`;$('paymentAccountName').value=x.account_name||'';$('paymentPublicKey').value=x.public_key||'';$('paymentSecretKey').value='';$('paymentSecretKey').placeholder=x.configured?'Enter a new secret key to replace the saved one':'Secret API key';$('paymentConfigMode').value=x.mode||'test';$('paymentConfigModal').classList.remove('hidden')}catch(e){toast(e.message,true)}}
