async function testPaymentConnection(provider){try{const d=await api(`/api/payments/${provider}/connection`);toast(d.message, !d.connected);const el=$(provider+'Status');if(el)el.textContent=d.message+` Mode: ${(d.mode||'test').toUpperCase()}.`;await loadPaymentHub()}catch(e){toast(e.message,true)}}
async function reconcilePayment(id){const note=prompt('Optional reconciliation note:','Verified against gateway record');if(note===null)return;try{await api('/api/payments/reconcile',{method:'POST',body:JSON.stringify({payment_id:id,status:'reconciled',note})});toast('Payment reconciled successfully.');await loadPaymentHub()}catch(e){toast(e.message,true)}}
async function pay(plan){
  try{
    toast('Opening secure Flutterwave subscription checkout…');
    const d=await api('/api/payments/flutterwave/initialize',{method:'POST',body:JSON.stringify({plan})});
    if(!d?.checkout_url)throw new Error('Flutterwave did not return a subscription checkout link.');
    // Open Flutterwave's hosted checkout in its own window rather than navigating BIGJOE away,
    // so the person doesn't lose their place in the app. Native apps (Capacitor) and popup
    // blockers can prevent window.open from returning a usable window, so fall back to a
    // normal redirect in that case — the payment still completes either way.
    const win=isNativeApp()?null:window.open(d.checkout_url,'bigjoe_flutterwave_checkout','noopener,noreferrer,width=480,height=760');
    if(!win){ location.href=d.checkout_url; return; }
    toast('Complete your payment in the Flutterwave window that just opened.');
    const poll=setInterval(async()=>{
      if(win.closed){
        clearInterval(poll);
        toast('Checking payment status…');
        try{
          await loadPlans();
          if(String(user?.plan)===String(plan)) toast(`🎉 Your BIGJOE ${title(plan)} plan is now active.`);
          else toast('If your payment succeeded, it can take a few seconds to reflect — refresh Plans to check again.');
        }catch{}
      }
    },1000);
  }catch(e){toast(e.message,true)}
}
