async function loadFinancialControl(){try{setAccountingPreset();const start=$('accountingStart')?.value||'',end=$('accountingEnd')?.value||'';const scope=accountingBranchViewId==='all'?'all':(activeBranchId||'');const [fs,tb]=await Promise.all([api(`/api/accounting/financial-statements?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}${scope?`&branch_id=${encodeURIComponent(scope)}`:''}`),api(`/api/accounting/trial-balance?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}${scope?`&branch_id=${encodeURIComponent(scope)}`:''}`)]);const bs=fs.balance_sheet||{},pl=fs.profit_loss||{},cf=fs.cash_flow||{};const balanced=Math.abs(Number(tb.difference||0))<0.01;const sheetBalanced=Math.abs(Number(bs.balance_check||0))<0.01;const tile=(label,value,ok=true)=>`<div class="control-tile ${ok?'control-ok':'control-warn'}"><span>${esc(label)}</span><b>${value}</b></div>`;const openingAdj=Math.abs(Number(tb.opening_balance_adjustment||0));const openingText=openingAdj>=0.01?` · <b>Opening Balance Equity:</b> ${money(openingAdj)}`:'';$('financialControl').innerHTML=tile('Trial Balance',balanced?'✓ Balanced':'⚠ Review',balanced)+tile('Balance Sheet',sheetBalanced?'✓ Balanced':'⚠ Review',sheetBalanced)+tile('Net Profit / Loss',money(pl.net_profit),Number(pl.net_profit||0)>=0)+tile('Closing Cash',money(cf.closing_cash),Number(cf.closing_cash||0)>=0)+`<div class="settings-note" style="grid-column:1/-1"><b>Debits:</b> ${money(tb.total_debit)} · <b>Credits:</b> ${money(tb.total_credit)} · <b>Difference:</b> ${money(Math.abs(tb.difference||0))}${openingText} · <b>Assets:</b> ${money(bs.total_assets)} · <b>Liabilities + Equity:</b> ${money((bs.total_liabilities||0)+(bs.total_equity||0))}</div>`;}catch(e){if($('financialControl'))$('financialControl').innerHTML=`<div class="empty">${esc(e.message||'Unable to run financial control check.')}</div>`;toast(e.message,true)}}

async function loadFinancialStatements(){try{setAccountingPreset();const start=$('accountingStart')?.value||'',end=$('accountingEnd')?.value||'';const scope=accountingBranchViewId==='all'?'all':(activeBranchId||'');const d=await api(`/api/accounting/financial-statements?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}${scope?`&branch_id=${encodeURIComponent(scope)}`:''}`);financialStatementsData=d;const pl=d.profit_loss||{},bs=d.balance_sheet||{},cf=d.cash_flow||{};const row=(label,value,cls='')=>`<div class="fs-row ${cls}"><span>${esc(label)}</span><b>${money(value)}</b></div>`;const rows=a=>(a||[]).map(x=>row(x.label,x.amount)).join('');const expenseRows=(pl.expense_breakdown||[]).length?(pl.expense_breakdown||[]).map(x=>`<tr><td>${esc(x.category)}</td><td>${money(x.total)}</td></tr>`).join(''):`<tr><td colspan="2" class="muted">No operating expenses in this period.</td></tr>`;const channelRows=(cf.by_channel||[]).length?(cf.by_channel||[]).map(x=>`<tr><td>${esc(title(x.method))}</td><td class="${x.total>=0?'income-text':'danger-text'}">${x.total>=0?'+':'-'}${money(Math.abs(x.total))}</td></tr>`).join(''):`<tr><td colspan="2" class="muted">No cash movements in this period.</td></tr>`;const check=Math.abs(Number(bs.balance_check||0))<0.01;$('financialStatements').innerHTML=`<div class="fs-banner"><div><b>${esc((d.owner?.name||'Your')+' — Financial Statements')}</b><span>Period: ${esc(d.period.start)} to ${esc(d.period.end)}</span></div><span class="badge ${check?'ok':'low'}">${check?'Balanced':'Review balance'}</span></div><div class="fs-grid"><section class="fs-panel"><h4>📈 Profit & Loss Statement</h4>${row('Sales Revenue',pl.revenue)}${row('Cost of Goods Sold',pl.cogs)}${row('Gross Profit',pl.gross_profit,'strong')}${row('Other Income',pl.other_income)}${row('Operating Expenses',pl.operating_expenses)}${row('Net Profit / Loss',pl.net_profit,Number(pl.net_profit)>=0?'total-positive':'total-negative')}<div class="fs-subtable"><h5>Expense Breakdown</h5><table><thead><tr><th>Category</th><th>Amount</th></tr></thead><tbody>${expenseRows}</tbody></table></div></section><section class="fs-panel"><h4>⚖ Balance Sheet</h4><h5>Assets</h5>${rows(bs.assets)}<div class="fs-total">${row('Total Assets',bs.total_assets)}</div><h5>Liabilities</h5>${rows(bs.liabilities)}<div class="fs-total">${row('Total Liabilities',bs.total_liabilities)}</div><h5>Equity</h5>${rows(bs.equity)}<div class="fs-total">${row('Total Equity',bs.total_equity)}</div><div class="fs-check">${row('Balance Check',bs.balance_check,check?'income-text':'danger-text')}</div></section><section class="fs-panel"><h4>💵 Cash Flow Statement</h4>${row('Opening Cash',cf.opening_cash)}${row('Cash Inflows',cf.cash_in,'income-text')}${row('Cash Outflows',cf.cash_out,'danger-text')}${row('Net Cash Movement',cf.net_cash,cf.net_cash>=0?'total-positive':'total-negative')}${row('Closing Cash',cf.closing_cash,'strong')}<div class="fs-subtable"><h5>Cash Movement by Channel</h5><table><thead><tr><th>Channel</th><th>Net Movement</th></tr></thead><tbody>${channelRows}</tbody></table></div></section></div><p class="muted small fs-note">These statements are generated from your BIGJOE records. The balance sheet uses tracked cash, receivables, inventory, payables and equity data; inventory is based on current stock quantities and cost prices.</p>`}catch(e){toast(e.message,true)}}
let trialBalanceData=null;
async function loadTrialBalance(silent=false){try{setAccountingPreset();const start=$('accountingStart')?.value||'',end=$('accountingEnd')?.value||'';const scope=accountingBranchViewId==='all'?'all':(activeBranchId||'');const d=await api(`/api/accounting/trial-balance?start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}${scope?`&branch_id=${encodeURIComponent(scope)}`:''}`);trialBalanceData=d;const rows=(d.rows||[]).map(x=>`<tr><td>${esc(x.code)}</td><td><b>${esc(x.name)}</b></td><td>${esc(title(x.type))}</td><td>${x.debit?money(x.debit):'—'}</td><td>${x.credit?money(x.credit):'—'}</td><td class="${x.balance>=0?'income-text':'danger-text'}">${money(Math.abs(x.balance))} ${x.balance>=0?'Dr':'Cr'}</td></tr>`);const balanced=Math.abs(Number(d.difference||0))<0.01;const openingNote=Math.abs(Number(d.opening_balance_adjustment||0))>=0.01?` · Opening balance equity adjustment: <b>${money(Math.abs(d.opening_balance_adjustment))}</b>`:'';const footer=`<div class="settings-note" style="margin-top:12px"><b>${balanced?'✓ Trial Balance is balanced':'⚠ Trial Balance needs review'}</b> · Total Debits: <b>${money(d.total_debit)}</b> · Total Credits: <b>${money(d.total_credit)}</b> · Difference: <b>${money(Math.abs(d.difference||0))}</b>${openingNote}</div>`;$('trialBalance').innerHTML=rows.length?`<table><thead><tr><th>Code</th><th>Account</th><th>Type</th><th>Debit</th><th>Credit</th><th>Balance</th></tr></thead><tbody>${rows.join('')}</tbody></table>${footer}`:`<div class="empty">No accounting activity in this period.</div>${footer}`;const select=$('ledgerAccount');if(select){const current=select.value;select.innerHTML='<option value="">Select account</option>'+(d.rows||[]).map(x=>`<option value="${esc(x.code)}">${esc(x.code)} — ${esc(x.name)}</option>`).join('');if(current && [...select.options].some(o=>o.value===current))select.value=current;}if(select?.value)await loadGeneralLedger(true);return d}catch(e){if(!silent)toast(e.message,true);return null}}
async function loadGeneralLedger(silent=false){try{const code=$('ledgerAccount')?.value||'';if(!code){$('generalLedger').innerHTML='<div class="empty">Select an account above to view its ledger.</div>';return}setAccountingPreset();const start=$('accountingStart')?.value||'',end=$('accountingEnd')?.value||'';const scope=accountingBranchViewId==='all'?'all':(activeBranchId||'');const d=await api(`/api/accounting/general-ledger?account=${encodeURIComponent(code)}&start=${encodeURIComponent(start)}&end=${encodeURIComponent(end)}${scope?`&branch_id=${encodeURIComponent(scope)}`:''}`);const rows=(d.rows||[]).map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.reference||'—')}</td><td>${esc(x.description)}</td><td>${esc(title(x.source))}</td><td>${x.debit?money(x.debit):'—'}</td><td>${x.credit?money(x.credit):'—'}</td><td><b>${money(Math.abs(x.balance))} ${x.balance>=0?'Dr':'Cr'}</b></td></tr>`);$('generalLedger').innerHTML=`<div class="settings-note"><b>${esc(d.account?.name||code)}</b> · Opening: <b>${money(Math.abs(d.opening_balance||0))} ${(Number(d.opening_balance||0)>=0?'Dr':'Cr')}</b> · Closing: <b>${money(Math.abs(d.closing_balance||0))} ${(Number(d.closing_balance||0)>=0?'Dr':'Cr')}</b></div>`+(rows.length?`<table><thead><tr><th>Date</th><th>Reference</th><th>Description</th><th>Source</th><th>Debit</th><th>Credit</th><th>Running Balance</th></tr></thead><tbody>${rows.join('')}</tbody></table>`:'<div class="empty">No ledger activity for this account in the selected period.</div>');}catch(e){if(!silent)toast(e.message,true)}}
function exportTrialBalanceCSV(){const d=trialBalanceData;if(!d)return loadTrialBalance().then(exportTrialBalanceCSV);const rows=[['BIGJOE Trial Balance'],['Account Holder',d.owner?.name||''],['Period',d.period.start,d.period.end],[],['Code','Account','Type','Debit','Credit','Balance'],...(d.rows||[]).map(x=>[x.code,x.name,x.type,x.debit,x.credit,x.balance]),[],['TOTAL','','',d.total_debit,d.total_credit,d.difference]];const csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`BIGJOE_Trial_Balance_${d.period.start||'all'}_to_${d.period.end||'all'}.csv`;a.click();URL.revokeObjectURL(a.href)}

function printFinancialStatements(){if(!financialStatementsData)return loadFinancialStatements().then(()=>printFinancialStatements());const w=window.open('','_blank','width=1000,height=800');if(!w)return toast('Please allow pop-ups to print the statements.',true);const d=financialStatementsData,owner=d.owner?.name||'Account Holder',html=$('financialStatements').innerHTML;w.document.write(`<!doctype html><html><head><title>${esc(owner)} - Financial Statements</title><style>body{font-family:Arial,sans-serif;color:#172033;padding:30px}h1{margin:0 0 5px}h2,h3,h4,h5{margin:16px 0 8px}.fs-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.fs-panel{border:1px solid #ddd;border-radius:10px;padding:16px}.fs-panel:nth-child(3){grid-column:1/-1}.fs-row{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #eee}.strong b,.total-positive b,.total-negative b{font-size:18px}.total-negative b{color:#b42318}.income-text b{color:#147a45}.danger-text b{color:#b42318}.fs-total{border-top:2px solid #172033;margin-top:8px}.fs-subtable table{width:100%;border-collapse:collapse}.fs-subtable th,.fs-subtable td{padding:7px;border-bottom:1px solid #eee;text-align:left}.fs-banner{display:flex;justify-content:space-between;border-bottom:2px solid #172033;padding-bottom:12px;margin-bottom:18px}.fs-banner span{display:block;color:#667085;margin-top:5px}.badge{padding:5px 9px;border-radius:20px;background:#eef2f7}.ok{color:#17733a}.low{color:#b42318}@media print{body{padding:10px}.fs-grid{grid-template-columns:1fr}.fs-panel:nth-child(3){grid-column:auto}}</style></head><body><h1>${esc(owner)}'s Financial Statements</h1><p>BIGJOE Business AI • ${esc(d.period.start)} to ${esc(d.period.end)}</p>${html}</body></html>`);w.document.close();w.focus();setTimeout(()=>w.print(),250)}
function exportFinancialStatementsCSV(){const d=financialStatementsData;if(!d)return loadFinancialStatements().then(()=>exportFinancialStatementsCSV());const rows=[['BIGJOE Financial Statements'],['Account Holder',d.owner?.name||''],['Period',d.period.start,d.period.end],[],['PROFIT & LOSS'],['Sales Revenue',d.profit_loss.revenue],['Cost of Goods Sold',d.profit_loss.cogs],['Gross Profit',d.profit_loss.gross_profit],['Other Income',d.profit_loss.other_income],['Operating Expenses',d.profit_loss.operating_expenses],['Net Profit / Loss',d.profit_loss.net_profit],[],['BALANCE SHEET'],['Total Assets',d.balance_sheet.total_assets],['Total Liabilities',d.balance_sheet.total_liabilities],['Total Equity',d.balance_sheet.total_equity],['Balance Check',d.balance_sheet.balance_check],[],['CASH FLOW'],['Opening Cash',d.cash_flow.opening_cash],['Cash Inflows',d.cash_flow.cash_in],['Cash Outflows',d.cash_flow.cash_out],['Net Cash Movement',d.cash_flow.net_cash],['Closing Cash',d.cash_flow.closing_cash]];const csv=rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`BIGJOE_Financial_Statements_${d.period.start}_to_${d.period.end}.csv`;a.click();URL.revokeObjectURL(a.href)}
function clearAccountingFilters(){if($('accountingStart'))$('accountingStart').value='';if($('accountingEnd'))$('accountingEnd').value='';loadAccounting()}
