function accountingRequiredAccountType(classification){return ({income:'income',expense:'expense',owner_capital:'equity',owner_withdrawal:'equity',loan_received:'liability',loan_repayment:'liability',asset_purchase:'asset'})[classification]||'income'}
function refreshAccountingEntryAccounts(){const c=$('accountingEntryType')?.value||'income',type=accountingRequiredAccountType(c),paymentCodes=['CASH','BANK','POS','FLUTTERWAVE'],accounts=(accountingData.accounts||[]).filter(a=>a.type===type && !(c==='asset_purchase'&&paymentCodes.includes(String(a.code||'').toUpperCase())));$('accountingEntryAccountLabel').firstChild.textContent=({income:'Income account',expense:'Expense account',owner_capital:"Owner's equity account",owner_withdrawal:"Owner's equity account",loan_received:'Liability account',loan_repayment:'Liability account',asset_purchase:'Asset account (what you purchased)'}[c]||'Account')+' ';$('accountingEntryAccount').innerHTML=accounts.map(a=>`<option value="${esc(a.code)}">${esc(a.name)}</option>`).join('');if(!accounts.length)$('accountingEntryAccount').innerHTML='<option value="">No suitable account</option>'}
function openAccountingEntryModal(){setAccountingPreset();renderBranchSelectors();const br=$('accountingEntryBranch');if(br){br.innerHTML=branches.filter(b=>b.active!==false).map(b=>`<option value="${esc(b.id)}">${esc(b.name)}${String(b.id)===String(activeBranchId)?' — Active':''}</option>`).join('');br.value=activeBranchId||'';}$('accountingEntryDate').value=new Date().toISOString().slice(0,10);$('accountingEntryType').value='income';$('accountingEntryDescription').value='';$('accountingEntryAmount').value='';$('accountingEntryReference').value='';$('accountingEntryNotes').value='';refreshAccountingEntryAccounts();$('accountingEntryModal').classList.remove('hidden')}
