async function submitAccountingEntry(e){e.preventDefault();try{const classification=$('accountingEntryType').value;if(!$('accountingEntryAccount').value)return toast('No suitable account is available for this transaction type. Add the required account first.',true);await api('/api/accounting/entries',{method:'POST',body:JSON.stringify({classification,entry_type:classification,date:$('accountingEntryDate').value,description:$('accountingEntryDescription').value,amount:Number($('accountingEntryAmount').value),account_code:$('accountingEntryAccount').value,payment_method:$('accountingEntryMethod').value,branch_id:$('accountingEntryBranch')?.value||activeBranchId,reference:$('accountingEntryReference').value,notes:$('accountingEntryNotes').value})});closeAccountingEntryModal();toast('Accounting entry saved and classified correctly.');loadAccounting()}catch(x){toast(x.message,true)}}
