let loyaltyData=null;
async function loadLoyalty(){try{const d=await api('/api/loyalty/overview');loyaltyData=d;const s=d.summary||{};$('loyaltyStats').innerHTML=`<div class="stat"><span>Loyalty Members</span><b>${s.members||0}</b></div><div class="stat"><span>Points Issued</span><b>${(s.points_issued||0).toLocaleString()}</b></div><div class="stat"><span>Points Redeemed</span><b>${(s.points_redeemed||0).toLocaleString()}</b></div><div class="stat"><span>Rewards</span><b>${s.rewards||0}</b></div><div class="stat"><span>Redemptions</span><b>${s.redemptions||0}</b></div>`;const c=d.config||{};['Rate','Bronze','Silver','Gold','Platinum'].forEach((x,i)=>{const el=$('loyalty'+x);if(el)el.value=[c.points_per_naira,c.bronze,c.silver,c.gold,c.platinum][i]});$('loyaltyLevels').innerHTML=Object.entries(d.levels||{}).map(([k,v])=>`<div class="insight"><b>${esc(k)}</b><span>${v} customer(s)</span></div>`).join('');$('loyaltyCustomers').innerHTML=(d.customers||[]).length?`<table><thead><tr><th>Customer</th><th>Points</th><th>Level</th><th>Spent</th><th>Redeemed</th></tr></thead><tbody>${d.customers.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${c.points.toLocaleString()}</td><td><span class="segment-pill">${esc(c.level)}</span></td><td>${money(c.total_spent||0)}</td><td>${Number(c.redeemed||0).toLocaleString()}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No customers yet.</div>';$('rewardsTable').innerHTML=(d.rewards||[]).length?`<table><thead><tr><th>Reward</th><th>Points</th><th>Value</th><th>Action</th></tr></thead><tbody>${d.rewards.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.points}</td><td>${money(r.value)}</td><td><button onclick="deleteReward('${r.id}')">Delete</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No rewards yet.</div>';$('loyaltyCustomerSelect').innerHTML='<option value="">Select customer</option>'+(d.customers||[]).filter(c=>c.points>0).map(c=>`<option value="${c.id}">${esc(c.name)} — ${c.points} pts</option>`).join('');$('loyaltyRewardSelect').innerHTML='<option value="">Select reward</option>'+(d.rewards||[]).filter(r=>r.active!==false).map(r=>`<option value="${r.id}">${esc(r.name)} — ${r.points} pts</option>`).join('');const top=(d.customers||[]).filter(c=>c.points>0).slice(0,3);$('loyaltyInsight').innerHTML=top.length?top.map(c=>`<div class="insight"><b>💎 ${esc(c.name)} — ${esc(c.level)}</b><span>${c.points} points. Consider a loyalty reward to encourage the next purchase.</span></div>`).join(''):'<div class="insight"><b>Start building loyalty</b><span>Link customers to completed POS sales so BIGJOE can award points automatically.</span></div>';}catch(e){toast(e.message,true)}}
