let marketingData=null, selectedMarketingSegment='all';
async function loadMarketing(){try{const d=await api('/api/marketing/overview');marketingData=d;const s=d.summary||{};
$('campaignCustomer').innerHTML='<option value="">Use selected segment</option>'+(customers||[]).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');
$('marketingStats').innerHTML=`<div class="stat"><span>Total Customers</span><b>${s.customers||0}</b></div><div class="stat"><span>Active Customers</span><b>${s.active||0}</b></div><div class="stat"><span>VIP Customers</span><b>${s.vip||0}</b></div><div class="stat"><span>At Risk</span><b>${s.at_risk||0}</b></div><div class="stat"><span>Campaigns</span><b>${s.campaigns||0}</b></div>`;
$('marketingSegments').innerHTML=Object.entries(d.segments||{}).map(([k,n])=>{const m=d.messages[k]||d.messages.all;return `<button class="segment-card" onclick="selectMarketingSegment('${k}')"><b>${esc(m.label)}</b><strong>${n}</strong><span>Create campaign</span></button>`}).join('');
$('marketingCampaigns').innerHTML=(d.campaigns||[]).length?`<table><thead><tr><th>Campaign</th><th>Segment</th><th>Channel</th><th>Status</th><th>Offer</th><th>Created</th><th>Actions</th></tr></thead><tbody>${d.campaigns.map(c=>`<tr><td><b>${esc(c.title)}</b></td><td>${esc((d.messages[c.segment]||d.messages.all).label)}</td><td>${esc(c.channel)}</td><td><span class="segment-pill ${esc(c.status)}">${esc(c.status)}</span></td><td>${esc(c.offer||'—')}</td><td>${new Date(c.created_at).toLocaleString()}</td><td><button onclick="setCampaignStatus('${c.id}','active')">Activate</button> <button onclick="deleteMarketingCampaign('${c.id}')">Delete</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No campaigns created yet.</div>';
$('marketingRecommendations').innerHTML=[['vip','Protect VIP customers',s.vip?`Create a VIP appreciation campaign for ${s.vip} customer(s).`:'No VIP customers yet.'],['at_risk','Win back at-risk customers',s.at_risk?`Reach ${s.at_risk} at-risk customer(s) before they become dormant.`:'No at-risk customers currently.'],['dormant','Reactivate dormant customers',s.dormant?`Consider a simple comeback offer for ${s.dormant} dormant customer(s).`:'No dormant customers currently.']].map(x=>`<div class="insight"><b>${x[1]}</b><span>${x[2]}</span></div>`).join('');
selectMarketingSegment(selectedMarketingSegment);
}catch(e){toast(e.message,true)}}
function selectMarketingSegment(k){selectedMarketingSegment=k;const d=marketingData;if(!d)return;const m=d.messages[k]||d.messages.all;$('campaignTitle').value=m.title;$('campaignMessage').value=m.message;const selected=$('campaignCustomer').value;const sample=(d.customer_samples&&d.customer_samples[k])||[];const preview=selected?(()=>{const c=(d.customers||[]).find(x=>String(x.id)===String(selected));return c?[`<div class="insight"><b>${esc(c.name)}</b><span>${esc(m.message).replace(/\{\{name\}\}/g,c.name).replace(/\{\{business\}\}/g,businessName())}</span></div>`].join(''):''})():sample.slice(0,3).map(c=>`<div class="insight"><b>${esc(c.name)}</b><span>${esc(m.message).replace(/\{\{name\}\}/g,c.name).replace(/\{\{business\}\}/g,businessName())}</span></div>`).join('');$('marketingPreview').innerHTML=preview||`<div class="insight"><b>Personalised message</b><span>${esc(m.message).replace(/\{\{name\}\}/g,'Customer').replace(/\{\{business\}\}/g,businessName())}</span></div>`;}
async function createMarketingCampaign(){try{const title=$('campaignTitle').value.trim(),message=$('campaignMessage').value.trim();if(!message)throw new Error('Campaign message is required.');await api('/api/marketing/campaigns',{method:'POST',body:JSON.stringify({title,segment:selectedMarketingSegment,target_customer_id:$('campaignCustomer').value||null,message,channel:$('campaignChannel').value,offer:$('campaignOffer').value,discount_type:$('campaignDiscountType').value,discount_value:Number($('campaignDiscountValue').value||0)})});toast('Marketing campaign created successfully.');await loadMarketing()}catch(e){toast(e.message,true)}}
async function createMarketingCampaign(){try{const title=$('campaignTitle').value.trim(),message=$('campaignMessage').value.trim();if(!message)throw new Error('Campaign message is required.');await api('/api/marketing/campaigns',{method:'POST',body:JSON.stringify({title,segment:selectedMarketingSegment,message,channel:$('campaignChannel').value,offer:$('campaignOffer').value})});toast('Marketing campaign created successfully.');await loadMarketing();}catch(e){toast(e.message,true)}}
async function setCampaignStatus(id,status){try{await api('/api/marketing/campaigns/'+id,{method:'PUT',body:JSON.stringify({status})});toast('Campaign status updated.');await loadMarketing()}catch(e){toast(e.message,true)}}
async function deleteMarketingCampaign(id){if(!confirm('Delete this campaign?'))return;try{await api('/api/marketing/campaigns/'+id,{method:'DELETE'});toast('Campaign deleted.');await loadMarketing()}catch(e){toast(e.message,true)}}
async function copyMarketingMessage(){try{await navigator.clipboard.writeText($('campaignMessage').value);toast('Message copied to clipboard.')}catch(e){toast('Unable to copy message. Please select and copy it manually.',true)}}


async function loadProcurementIntelligence(){try{const d=await api('/api/procurement-intelligence');const s=d.summary||{};$('procurementStats').innerHTML=`<div class="stat"><span>Suppliers with Purchases</span><b>${s.suppliers_with_purchases||0}</b></div><div class="stat"><span>Total Purchases</span><b>${money(s.total_purchases)}</b></div><div class="stat danger"><span>Outstanding Payables</span><b>${money(s.outstanding_payables)}</b></div><div class="stat"><span>Potential Savings</span><b>${money(s.potential_savings)}</b></div><div class="stat danger"><span>Price Risks</span><b>${s.price_risks||0}</b></div>`;
$('procurementSuppliers').innerHTML=(d.suppliers||[]).length?`<table><thead><tr><th>Supplier</th><th>Orders</th><th>Total</th><th>Avg Order</th><th>Outstanding</th><th>Received</th></tr></thead><tbody>${d.suppliers.map(x=>`<tr><td><b>${esc(x.supplier_name)}</b></td><td>${x.orders}</td><td>${money(x.total)}</td><td>${money(x.avg_order)}</td><td>${money(x.outstanding)}</td><td>${Number(x.received_rate||0).toFixed(1)}%</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No supplier purchases available yet.</div>';
$('procurementRisks').innerHTML=(d.price_risks||[]).length?`<table><thead><tr><th>Product</th><th>Previous Cost</th><th>Latest Cost</th><th>Change</th><th>Supplier</th></tr></thead><tbody>${d.price_risks.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${x.previous_cost===null?'—':money(x.previous_cost)}</td><td>${money(x.current_cost)}</td><td><span class="badge danger-badge">+${Number(x.change_pct).toFixed(1)}%</span></td><td>${esc(x.supplier_name||'—')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No significant purchase-cost increases detected.</div>';
$('procurementSavings').innerHTML=(d.savings||[]).length?`<table><thead><tr><th>Product</th><th>Best Cost</th><th>Latest Cost</th><th>Saving/Unit</th><th>Estimated Stock Saving</th></tr></thead><tbody>${d.savings.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${money(x.best_cost)}</td><td>${money(x.current_cost)}</td><td>${money(x.potential_saving_per_unit)}</td><td><b>${money(x.estimated_saving)}</b></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No procurement savings opportunity detected yet.</div>';
$('procurementRecommendations').innerHTML=(d.recommendations||[]).map(x=>`<div class="insight"><b>${x.severity==='high'?'⚠️':x.severity==='positive'?'✅':'🔔'} ${esc(x.title)}</b><span>${esc(x.text)}</span></div>`).join('');}catch(e){toast(e.message,true)}}


// BIGJOE v38.0 — Staff, Roles & Permissions
let staffData=null;
async function loadStaff(){try{const d=await api('/api/staff');staffData=d;const rows=d.staff||[];$('staffStats').innerHTML=`<div class="stat"><span>Team Members</span><b>${rows.length}</b></div><div class="stat"><span>Active Staff</span><b>${rows.filter(x=>x.active).length}</b></div><div class="stat"><span>Managers</span><b>${rows.filter(x=>x.role==='manager').length}</b></div><div class="stat"><span>Cashiers</span><b>${rows.filter(x=>x.role==='cashier').length}</b></div>`;$('staffTable').innerHTML=rows.length?`<table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Branch</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.name)}</b></td><td>${esc(x.email)}</td><td><span class="badge">${esc(title(x.role))}</span></td><td>${esc((d.branches||[]).find(b=>b.id===x.branch_id)?.name||'All / Main business')}</td><td><span class="badge ${x.active?'ok':'low'}">${x.active?'Active':'Disabled'}</span></td><td><button class="link" onclick="toggleStaff('${x.id}',${x.active})">${x.active?'Disable':'Enable'}</button> <button class="danger-link" onclick="deleteStaff('${x.id}')">Delete</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">No staff accounts yet. Add your first team member when you are ready.</div>';}catch(e){toast(e.message,true)}}
function openStaffModal(){if(!staffData)return loadStaff().then(openStaffModal);$('staffName').value='';$('staffEmail').value='';$('staffPassword').value='';$('staffRole').value='cashier';$('staffBranch').innerHTML='<option value="">All / Main business</option>'+(staffData.branches||[]).map(b=>`<option value="${b.id}">${esc(b.name)}</option>`).join('');updateStaffRoleHelp();$('staffModal').classList.remove('hidden')}
function closeStaffModal(){$('staffModal').classList.add('hidden')}
function updateStaffRoleHelp(){const m={manager:'Most daily business operations. Cannot manage staff or change the owner account.',cashier:'Sales/POS, customer records and AI assistance.',inventory:'Products, stock, suppliers and purchases.',accountant:'Expenses, reports, financial centre and accounting.',viewer:'Dashboard, reports and customer viewing.'};$('staffRoleHelp').textContent=m[$('staffRole').value]||''}
async function submitStaff(e){e.preventDefault();try{const d=await api('/api/staff',{method:'POST',body:JSON.stringify({name:$('staffName').value,email:$('staffEmail').value,password:$('staffPassword').value,role:$('staffRole').value,branch_id:$('staffBranch').value||null})});closeStaffModal();toast(`${d.staff.name} staff account created successfully.`);await loadStaff()}catch(e){toast(e.message,true)}}
async function toggleStaff(id,active){try{await api('/api/staff/'+id,{method:'PUT',body:JSON.stringify({active:!active})});toast(active?'Staff login disabled.':'Staff login enabled.');await loadStaff()}catch(e){toast(e.message,true)}}
async function deleteStaff(id){if(!confirm('Delete this staff login? Their business records will remain.'))return;try{await api('/api/staff/'+id,{method:'DELETE'});toast('Staff login deleted.');await loadStaff()}catch(e){toast(e.message,true)}}


/* BIGJOE v40.0 — Data Protection & Audit Centre */
let auditRows=[];
async function loadDataAudit(){
  try{
    const q=new URLSearchParams({search:$('auditSearch')?.value||'',tool:$('auditTool')?.value||'',start:$('auditStart')?.value||'',end:$('auditEnd')?.value||''});
    const d=await api('/api/data-audit?'+q.toString()); auditRows=d.activity||[];
    const tools=[...new Set(auditRows.map(x=>x.tool).filter(Boolean))].sort();
    const sel=$('auditTool'); if(sel){const cur=sel.value;sel.innerHTML='<option value="">All modules</option>'+tools.map(t=>`<option value="${esc(t)}">${esc(title(t.replace(/[-_]/g,' ')))}</option>`).join('');if(tools.includes(cur))sel.value=cur;}
    const h=d.health||{};
    $('auditHealth').innerHTML=`<div class="stat"><span>Products</span><b>${h.products||0}</b></div><div class="stat"><span>Customers</span><b>${h.customers||0}</b></div><div class="stat"><span>Sales</span><b>${h.sales||0}</b></div><div class="stat"><span>Branches</span><b>${h.branches||0}</b></div><div class="stat ${h.low_stock?'danger':''}"><span>Low Stock</span><b>${h.low_stock||0}</b></div><div class="stat ${h.expired?'danger':''}"><span>Expired Products</span><b>${h.expired||0}</b></div>`;
    $('auditProtectionBadge').textContent=d.protection?.status||'Protected';
    $('auditTable').innerHTML=auditRows.length?`<table><thead><tr><th>Date & Time</th><th>User</th><th>Module</th><th>Action / Reference</th><th>Details</th></tr></thead><tbody>${auditRows.map(x=>`<tr><td>${new Date(x.created_at).toLocaleString('en-NG')}</td><td>${esc(x.user_name||'Business Owner')}</td><td><span class="badge">${esc(title(String(x.tool||'activity').replace(/[-_]/g,' ')))}</span></td><td><b>${esc(x.input_text||'Activity')}</b></td><td>${esc(x.output_text||'')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">No audit activity matches your filters.</div>';
  }catch(e){toast(e.message,true)}
}
function downloadBusinessBackup(){window.location.href='/api/data-audit/backup'}
function downloadAuditCsv(){window.location.href='/api/data-audit/export'}

// BIGJOE v50.0 — Business Command Center
async function loadCommandCenter(){try{
 const d=await api('/api/command-center'); const s=d.summary||{},h=d.health||{},c=d.counts||{};
 $('commandStats').innerHTML=`<div class="stat"><span>Monthly Revenue</span><b>${money(s.revenue)}</b></div><div class="stat"><span>Gross Profit</span><b>${money(s.gross_profit)}</b></div><div class="stat ${Number(s.net_profit)<0?'danger':''}"><span>Net Profit</span><b>${money(s.net_profit)}</b></div><div class="stat"><span>Revenue Change</span><b>${s.revenue_change===null?'—':(Number(s.revenue_change)>=0?'↑ ':'↓ ')+Math.abs(Number(s.revenue_change)).toFixed(1)+'%'}</b></div>`;
 $('commandHealthBadge').textContent=`${h.score||0}/100 • ${h.label||'Unknown'}`; $('commandHealthBadge').className=`badge ${Number(h.score)>=80?'success-badge':Number(h.score)>=60?'':'danger-badge'}`;
 $('commandHealth').innerHTML=`<div class="command-health-score"><b>${h.score||0}</b><span>/100</span></div><h3>${esc(h.label||'Unknown')}</h3><p class="muted">Management indicator based on sales momentum, gross margin, inventory pressure and execution.</p>`;
 $('commandTasks').innerHTML=`<div class="command-mini"><span>Open tasks</span><b>${c.open_tasks||0}</b></div><div class="command-mini"><span>Overdue tasks</span><b class="${c.overdue_tasks?'negative':''}">${c.overdue_tasks||0}</b></div><div class="command-mini"><span>Low-stock products</span><b class="${c.low_stock?'negative':''}">${c.low_stock||0}</b></div><button class="primary" onclick="showPage('smartActions',this)">Open Smart Action Center</button>`;
 $('commandAlerts').innerHTML=(d.alerts||[]).map(x=>`<div class="alert-item alert-${esc(x.level==='danger'?'high':x.level==='positive'?'positive':'medium')}"><b>${x.level==='danger'?'🔴':x.level==='warning'?'🟠':'🟢'} ${esc(x.title)}</b><span>${esc(x.text)}</span></div>`).join('');
 $('commandActions').innerHTML=(d.actions||[]).map(x=>`<div class="decision-card priority-${esc(x.priority)}"><div class="decision-card-top"><span class="decision-priority">${esc(title(x.priority))}</span></div><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p><button class="link" onclick="showPage('${esc(x.page)}',this)">Open related feature →</button></div>`).join('');
 $('commandSnapshot').innerHTML=`<div class="snapshot-row"><span>Products tracked</span><b>${c.products||0}</b></div><div class="snapshot-row"><span>Customers</span><b>${c.customers||0}</b></div><div class="snapshot-row"><span>Suppliers</span><b>${c.suppliers||0}</b></div><div class="snapshot-row"><span>Sales this month</span><b>${c.sales||0}</b></div><div class="snapshot-row"><span>Gross margin</span><b>${Number(s.margin||0).toFixed(1)}%</b></div>`;
}catch(e){toast(e.message,true)}}
